programs.sol:
"""Lexical taste/sensation and `void` responses, with `already` inhibition.

The strongest sensory response is to 味 (taste). It is smaller in compounds
such as 興味 (interest), and to English taste/flavor words. The unrelated
word and programming keyword `void` also excites this component. Rules distinguish
word forms and a few immediate contexts. 昧 is another positive lexical
exception. State keeps 80 recent characters and resets between documents.
Unlisted words and undecodable token fragments receive zero. Many weaker,
idiosyncratic responses are deliberately left unmodeled.
"""
import re

READS = ()

TASTE_WORDS = {'taste', 'flavor', 'flavors', 'tastes'}
TASTE_INFLECTIONS = {'tasting', 'flavored', 'flavoured'}
SEASONINGS = {'seasoned', 'seasoning', 'seasonings'}
COOKING_MEASURES = {'teaspoon', 'teaspoons', 'tablespoon', 'tablespoons'}
TASTE_COMPOUNDS = {'口味', '风味', '風味', '品味', '滋味', '调味', '气味', '一味'}
# Flavor, aftertaste, and lingering charm, all spelled with 味.
STRONG_TASTE_COMPOUNDS = {'味道', '的味道', '回味', '韵味'}
MEANING_AND_INTEREST = {'意味', '趣味'}


def response(token, recent):
    word = token.strip()
    lower = word.lower()
    if lower.lstrip('(<.,') == 'void':
        if lower.startswith('<'):
            return 2.0
        if lower.startswith('('):
            return 2.75
        if lower != 'void':
            return 2.4
        if word != 'void':
            return 2.4
        if token == 'void':
            return 3.5
        if '\t' in token:
            return 2.5
        if '@Test' in recent:
            return 2.4
        declaration = re.search(r'\b(public|protected|virtual)\s*$', recent)
        if '@Override' in recent or declaration:
            return 3.4
        if re.search(r'(=>|\b(?:be|is|and|of))\s*$', recent):
            return 2.6
        return 3.1
    if lower == 'already':
        return -1.6
    if word in {'bereits', 'すでに'}:
        return -1.25
    if word == 'déjà':
        return -0.75
    if word in {'уже', '已经', '已經'}:
        return -0.5
    if word == '味':
        if recent.endswith(('興', '醐', '気', '風')):
            return 5.0
        if recent.endswith('調'):
            return 6.2
        japanese = any('\u3040' <= c <= '\u30ff' for c in recent[-40:])
        return 7.9 if japanese else 8.8
    if word in STRONG_TASTE_COMPOUNDS:
        return 5.1
    if word in TASTE_COMPOUNDS:
        return 3.15
    if word in MEANING_AND_INTEREST or word == '异味':
        return 2.5
    if word in {'美味', '香味'}:
        return 1.75
    if word == '昧':  # Visually similar to 味, despite a different meaning.
        return 4.3
    if word in {'尝', '品尝'}:
        return 1.4
    if lower in TASTE_WORDS:
        return 2.85 if lower in {'taste', 'flavor'} else 2.6
    if lower in {'flavour', 'flavours'}:
        return 2.3
    if lower == 'tasted':
        return 1.7
    if lower in TASTE_INFLECTIONS:
        return 1.15
    if lower == 'flavorful':
        return 1.5
    if lower in {'tasty', 'savory', 'savoury'}:
        return 0.8
    if word in {'вкус', '맛'}:
        return 2.7
    if word in {'goût', 'vị'}:
        return 1.9
    if lower == 'sense':
        if re.search(r'\b(make|makes|made|making)\s*$', recent):
            return 0.2
        return 0.7 if word.islower() else 0.25
    if lower in {'senses', 'spirit', 'spirits', 'vibe', 'vibes'}:
        return 0.7 if word.islower() else 0.2
    if lower in {'smell', 'smells', 'odor', 'odour'}:
        return 1.15
    if lower == 'scent':
        return 0.8
    if lower in SEASONINGS:
        return 1.15
    if lower in {'powder', 'powders', 'powdered'} or lower in COOKING_MEASURES:
        return 0.6
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, recent)
    return (doc, (recent + token)[-80:]), value

programs.haiku:
"""Lexical detector for layers.0.mlp.down_proj:5249.

The component reads the current word and reports how strongly it is one of a few
concepts (the value is its size in the residual stream):
  * "void" in any form (code return type `private void`, `(void`, `Void`): about +3;
  * taste and flavour words (taste, tasted, flavor, flavour, goût, 味 and 回味 for
    taste or aftertaste): about +2.7, and 味 about +6;
  * "already" (and déjà, bereits, уже, すでに, 已经): negative, about -1.6 (English) and
    about -0.8 (other languages);
  * weaker, about +0.5: sense, smell, scent, spirit, and cooking or liquid words
    (powder, tablespoons, ounces, beverage, liquid), and boolean type names.
Everything else predicts 0. The program only looks at the newest token, with
punctuation and capitals stripped, so "(void", ".Void" and "\tvoid" all count.
"""

import re

VOID = {"void"}
TASTE = {"taste", "tastes", "tasted", "tasting", "flavor", "flavors", "flavour", "flavours", "goût"}
TASTE_ZH = {"味", "回味"}
ALREADY = {"already"}
ALREADY_OTHER = {"déjà", "bereits", "уже", "すでに", "已经"}
WEAK = {
    "sense", "senses", "smell", "scent", "spirit", "spirits", "seasoned",
    "powder", "powdered", "tablespoons", "teaspoon", "ounces", "beverage", "liquid",
    "bool", "boolean",
}

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = re.sub(r"[^\w]", "", token).lower()  # drop spaces, brackets, dots
    if token.strip() in TASTE_ZH:
        value = 6.0
    elif word in VOID:
        value = 3.0
    elif word in TASTE:
        value = 2.7
    elif word in ALREADY:
        value = -1.6
    elif word in ALREADY_OTHER:
        value = -0.8
    elif word in WEAK:
        value = 0.5
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Approximate this rare lexical response with a few recognizable word groups.

The largest observed positive responses are on the programming keyword `void`
and vocabulary about taste; `already` gives a strong negative response.
"""

READS = ()

TASTE_WORDS = {
    "taste", "tasted", "tastes", "tasting", "flavour", "flavor",
    "flavours", "flavors", "appetite", "powder",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "void":
        return None, 3.5
    if word == "already":
        return None, -1.7
    if word in TASTE_WORDS:
        return None, 3.0 if word in {"taste", "flavour", "flavor"} else 0.7
    if word == "sense":
        return None, 0.7
    return None, 0.0

programs.sol:
"""Signed spelling transitions into t/d fragments.

A short t/d fragment is usually positive after a consonant and negative after a
vowel.  These amplitudes are calibrated by broad letter families, not words
or token IDs.  Long fragments, word-initial spaces and title case weaken
or adjust the contrast.  Common Cyrillic, Greek and Arabic equivalents are included;
katakana t/d syllables respond particularly after the nasal ン.
Other alphabetic beginnings receive a tiny opposite-sign baseline.
"""
import unicodedata

READS = ()
VOWELS = set('aeiouyıæøœаеёиоуыэюяіїєѣαεηιουωاأإآوىيئؤی')

# Previous-letter families: letters, strength for t, strength for d.
ENDINGS = {
    'low vowels': ('aæаαاأإآ', -1.15, -0.78),
    'rounded vowels': ('ouøоуюοωوؤ', -0.98, -0.76),
    'y vowels': ('yы', -0.32, -0.05),
    'dental stops': ('tdтдτδتدطض', 0.40, 0.40),
    'sibilant s': ('sсσςسص', 0.50, 0.50),
    'labiodental f': ('fфφف', 1.45, 1.10),
    'h sounds': ('hхχحخه', 1.25, 0.75),
    'nasals': ('mnмнμνمن', 0.78, 0.68),
    'soft sign': ('ь', 0.80, 0.80),
    'hard sign': ('ъ', -0.60, -0.60),
    'consonant glide': ('й', 0.15, 0.15),
}
STRENGTH = {c: (t, d) for letters, t, d in ENDINGS.values() for c in letters}


def letter(c):
    if c.lower() == 'й':
        return 'й'
    return unicodedata.normalize('NFD', c.casefold())[0] if c else ''


def transition(first, last):
    """Contrast of the two sides of the boundary, before word-size damping."""
    vowel, voiced = last in VOWELS, first in 'dдδد'
    default = (-0.74, -0.37) if vowel else (0.90, 0.72)
    value = STRENGTH.get(last, default)[int(voiced)]
    if not voiced and last in 'dдδد':
        value = 0.80
    if first in 'тд':
        value *= 1.2 if vowel else 1.3
        if last == 'я':
            value *= 1.2
        if last == 'ы' and first == 'т':
            value -= 0.3
    elif first == 'τ':
        value = value * 1.25 if vowel else 1.05
    elif first in 'θδц':
        value *= 0.5
    elif first in 'تدط':
        value *= 1.6 if last in 'اأإآ' else 0.7
        if first == 'ط':
            value *= 0.65
    return value


def step(carry, prefix, upstream):
    doc, text = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    carry = (doc, text)
    word = text.lstrip()
    if not word or not previous:
        return carry, 0.0
    first, last = letter(word[0]), letter(previous[-1])
    n, vowel = len(word), last in VOWELS
    if first in 'タテトダデド':
        value = 1.4 if last == 'ン' else 1.0 if last == 'ル' else 0.0
        if last in 'アイウエオァィゥェォ':
            value = -0.9
        return carry, value * (1.0 if n == 1 else 0.7 if n == 2 else 0.15)
    if text[0].isspace() and n == 1:
        if first == 'т':
            value = -0.75 if vowel else -0.30 if last in 'ьй' else 0.0
            return carry, value * (0.2 if word.isupper() else 1.0)
        if first == 'τ':
            return carry, -0.10 if last == 'α' else 0.10 if vowel else 0.25
        if first == 'ت':
            return carry, -0.50 if vowel else -0.15
    if not last.isalpha():
        return carry, 0.0
    if first not in 'tdтдτδθцتدط':
        return carry, (0.012 if vowel else -0.012) if first.isalpha() else 0.0

    value = transition(first, last)
    value *= (1.1 if n == 1 else 1.0 if n == 2 else 0.75 if n == 3 else
              0.5 if n == 4 else 0.4 if n == 5 else 0.13)
    if word[0].isupper():
        value *= 0.2 if not word.isupper() else 0.75 if n == 1 else 1.0
    if n > 1:
        second = letter(word[1])
        if second in 'tdтдτδ':
            value *= 0.55
        elif second in 'hrwlрлρλ':
            value *= 1.15
        elif second in 'sсσς' and vowel:
            value *= 1.5
    if text[0].isspace():
        value *= 0.3 if n == 1 else 0.035
    return carry, float(value)

programs.haiku:
"""Word-internal dental syllables (layers.0.mlp.down_proj:5250).

What it responds to: short pieces of a word that the tokenizer split apart, where the
piece is a dental (t/d-like) syllable sitting inside the word, such as "te" in "vorte-
ilhaft", "ton", "ten", "ter", "de", "den", "tr" and "t" in "unich|t|ожить" or "Auf|tr|ag".
A piece counts only if it has no leading space (so it continues a word), is letters only,
and has at most three letters. Those pieces get a signed value from a small table: the
Latin t/d syllables are positive, and the t-like letters of Greek, Cyrillic and Thai are
negative. Everything else predicts 0.

The sign is not reliable across contexts, so the table gives a mean, not a fit to each
occurrence.
"""

# Latin dental syllables and fragments that tend to be positive (typical mean activation).
POSITIVE = {
    "te": 0.6, "ten": 0.5, "ter": 0.5, "ton": 0.6, "de": 0.55, "den": 0.6,
    "tr": 0.3, "the": 0.2, "t": 0.2, "d": 0.1, "dom": 0.2, "ty": 0.7,
}
# Non-Latin t-like letters, and "td", which tend to be negative.
NEGATIVE = {"τ": -0.3, "т": -0.4, "ท": -1.0, "td": -0.2}


def _is_word_piece(text):
    """No leading space, letters only, at most three letters."""
    return 0 < len(text) <= 3 and not text[0].isspace() and text.isalpha()


READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if not _is_word_piece(text):
        return carry, 0.0
    if text in POSITIVE:
        return carry, POSITIVE[text]
    return carry, NEGATIVE.get(text, 0.0)

programs.sol:
"""Approximate a lexical signal for learning and acquiring knowledge or goods.

'Learn' and its inflections get the strongest negative values. Teaching,
discovery, understanding, earning, receiving and forgetting get smaller ones.
A short multilingual vocabulary and split spellings extend these classes.
Machine/deep learning phrases are weaker; learning's grammatical complements
also receive a negative value. Casing, spelling boundaries and document starts
adjust the response. Everything else is zero, omitting many small responses.

Only the previous token is remembered, and it is reset at document boundaries.
These are fitted lexical rules, not a general semantic understanding detector.
"""

READS: tuple[str, ...] = ()
TEACHING = set('teach teaches teaching learner learners'.split())
DISCOVERY = set('discover discovers discovering realize realizes realized '
                'realizing realise realised'.split())
ACQUISITION = set('acquire acquired gain gains gained gaining'.split())
UNDERSTANDING = set('understand understands understood understanding knowing '
                    'knows comprehend'.split())
RECEIVING = set('receive received receives receiving obtain obtained '
               'derive derived hearing forget forgot'.split())
KNOWLEDGE_AND_GATHERING = set(
    'gather gathered gathering forgotten knowledge'.split()
)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    at_start = not carry or carry[0] != doc
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.0
    if word in {'learn', 'learned', 'learns', 'learnt', 'learning'}:
        if at_start:
            value = -9.4
        elif word == 'learning':
            value = -5.0
            if previous == 'machine':
                value = -1.65
            elif previous in {'deep', 'supervised'}:
                value = -3.0
            elif previous in {'reinforcement', 'language', 'kernel'}:
                value = -3.8
            elif token == 'learning':
                value = -3.5
        elif word in {'learns', 'learnt'}:
            value = -4.75
        else:
            value = -5.4
            if token.strip()[0].isupper():
                value = -4.6 if token.startswith(' ') else -5.8
            elif previous in {'will', 'you', 'i', "'ll", '’ll', 'students'}:
                value -= 0.6
    elif word in {'-learning', '.learning', '_learning'}:
        value = -3.0
    # A spelling split such as L + earning still names learning, not wages.
    elif (not token.startswith(' ') and word == 'earning'
          and previous.lstrip('([{<') == 'l'):
        value = -4.0
    elif (not token.startswith(' ') and word == 'earned'
          and previous in {'un', '-'}):
        value = -2.4
    elif (not token.startswith(' ') and previous == 'learn'
          and word in {'ed', 'ings'}):
        value = -4.6
    elif word in TEACHING or word in DISCOVERY:
        value = -1.15
    elif word in {'lesson', 'lessons'}:
        value = -1.0 if word == 'lesson' else -1.55
    elif word in {'earn', 'earns', 'earned', 'earning', 'earnings'}:
        value = -1.3 if word != 'earnings' else -0.7
    elif word == 'taught':
        value = -0.85
    elif word in {'discovered', 'discovery', 'discoveries', 'realization'}:
        value = -0.9
    elif word in ACQUISITION:
        value = -0.8
    elif word in UNDERSTANDING or word in RECEIVING:
        value = -0.45
    elif word in KNOWLEDGE_AND_GATHERING:
        value = -0.63
    elif word in {'misunderstood', 'misunderstanding'}:
        value = -0.9
    elif word == 'know':
        value = -0.18
    elif word == 'out' and previous in {'find', 'found', 'finding'}:
        value = -1.2
    elif word == 'out' and previous in {'figure', 'figured', 'figuring'}:
        value = -0.7
    elif word == 'out' and previous in {'check', 'checked', 'checking'}:
        value = -0.4
    elif word in {'学习', '學習', '学習'}:
        value = -2.5
    elif '学习' in word or '學習' in word or '学習' in word:
        value = -1.9
    elif '学会' in word:
        value = -3.4
    elif previous == '学' and word in {'ぶ', 'び', '習'}:
        value = -3.5 if word == '習' else -1.7
    elif word in {'学', '學', '習', '收获', '懂得', '明白', '得知'}:
        value = -1.4
    elif word in {'教', '教学', '知识', '获得', '获取', '懂', '悟'}:
        value = -0.7
    elif word in {'aprender', 'aprend'}:
        value = -3.6
    elif word in {'узнать', 'узна', 'учиться', 'تعلم', 'öğren'}:
        value = -1.8
    elif word.startswith(('обуч', 'науч', 'получ')):
        value = -0.7
    elif word in {'hiểu', 'học', '出会い', 'いただく', '塾'}:
        value = -1.0
    # The response continues onto grammatical complements of learning.
    if value == 0.0 and previous in {'learn', 'learned', 'learns', 'learnt',
                                    'learning'}:
        participle = previous == 'learning'
        if word in {'to', 'of'}:
            value = -1.2 if participle and word == 'to' else -1.9
        elif word == 'about':
            value = -1.25
        elif word in {'how', 'from', 'that'}:
            value = -0.55 if participle else -0.8
            if previous == 'learned' and word == 'that':
                value = -1.5
        elif word in {'the', 'a', 'more', 'their'}:
            value = -0.65 if participle else -0.95
    return (doc, word), float(value)

programs.luna:
"""A sparse lexical guess for a small learning-and-acquisition feature.

The strongest examples point to learning, understanding, finding out, and
getting or receiving something.  The component is usually quiet; this rule
uses negative pulses on those words and stays silent elsewhere.
"""

READS = ()

LEARNING = {
    "learn", "learning", "teach", "knowledge", "understand",
    "understanding", "comprehend", "knowing", "misunderstood",
}

ACQUIRING = {
    "gain", "regain", "gather", "gathered", "receive", "received",
    "receiving", "obtain", "obtained", "derive", "derived", "acquire",
    "acquired", "discover", "discovery", "forget", "forgot",
    "получить", "获得", "收获", "いただく", "させて頂", "塾",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    word = word.strip(" \t\r\n.,!?;:'\"()[]{}<>，。！？、")

    if word == "out":
        if prefix.position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2].strip().lower()
            if previous in {"find", "figure"}:
                return None, -1.2
        return None, 0.0

    if word in {"learn", "learning"}:
        value = -1.5
        if prefix.position > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
            if prefix.token_strings[-2].strip().lower() == "to":
                value = -3.0
        return None, value

    if word in LEARNING:
        return None, -0.8
    if word in ACQUIRING:
        return None, -0.65
    return None, 0.0

