    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    value = GRAMMAR.get(word, 0.001)
    last = tail[-1:]

    if word in JAPANESE and any('\u3040' <= c <= '\u30ff'
                                for c in tail[-40:]):
        value = JAPANESE[word]
    elif word == '得':
        if last in ATTAINMENT:
            value = -0.15
        elif last in VERBS:
            value = -0.58
    elif word == '地':
        repeated = (len(tail) >= 2 and tail[-1] == tail[-2]
                    and '\u4e00' <= last <= '\u9fff')
        if repeated:
            value = -0.46
        elif tail.endswith(MANNER):
            value = -0.37
    elif word == '向':
        if last in MOTION:
            value = -0.68
        elif last in NOMINAL_DIRECTION:
            value = -0.11
    elif word in {'进', '進'} and last in MOTION:
        value = -0.29

    lower = word.lower()
    if lower in REFLEXIVES:
        value = REFLEXIVES[lower]
    elif lower in {'nothing', 'anything'}:
        value = -0.08
    elif lower in {'something', 'everything'}:
        value = -0.035
    elif lower in {'instead', 'otherwise', 'alternatively'}:
        value = -0.07
    elif lower in {'during', 'while', 'meanwhile'}:
        value = -0.04
    elif lower in {'perhaps', 'maybe', 'possibly'}:
        value = 0.045 if word.islower() else 0.02
    elif token.startswith(' ') and word.islower():
        if word in HELP_VERBS:
            value = HELP_VERBS[word]
        elif word in {'helpful', 'useful', 'handy'}:
            value = 0.12
    if len(word) == 1 and word in '0123456789':
        value = DIGITS[int(word)]
    return (doc, (tail + token)[-60:]), float(value)

"""A mostly lexical need/want/have signal, with negative activation.

Need is strongest, want next, have weaker; inflections differ in strength.
Related wanting, lacking and seeming words also respond. Selected need/want
translations and stems respond more weakly. The previous token supplies
simple grammatical cues: 'the need' versus 'you need', or 'would like'.
Document starts and split-word completions have reduced strength. This is
not a general necessity detector; all other cases default to zero.
"""
READS = ()

VERBS = {
    'need': -6.55, 'needs': -6.15, 'needed': -4.50, 'needing': -4.45,
    'want': -2.85, 'wants': -3.0, 'wanted': -2.3, 'wanting': -2.65,
    'have': -0.93, 'has': -0.77, 'had': -0.79, 'having': -0.74,
}
RELATED = {
    **dict.fromkeys(('necessary', 'unnecessary', 'desire', 'desires',
                     'desirable', 'wish', 'wishes', 'wished', 'lack',
                     'lacks', 'seem', 'seems', 'seemed', 'possess', 'ought'), -0.85),
    **dict.fromkeys(('seek', 'seeks', 'seeking', 'sought', 'hope', 'hopes',
                     'goal', 'goals', 'interested', 'desired'), -0.5),
    **dict.fromkeys(('deserve', 'deserves', 'deserved', 'needy'), -2.2),
    'lacking': -1.3, 'likes': -1.0, 'loves': -0.5, 'hunger': -0.75,
}
# Words/stems for needing, wanting and necessity in other languages.
TRANSLATIONS = {
    '需要': -1.2, '需求': -1.0, '想要': -0.9, '我要': -0.4,
    'したい': -1.0, 'たい': -0.5, 'が必要': -1.2,
    'нуж': -2.7, 'нужно': -1.4, 'необходим': -0.9, 'необходимо': -0.5,
    'cần': -2.2, 'muốn': -0.7, 'besoin': -1.6, 'nécess': -1.2,
    'benöt': -2.0, 'potrze': -2.7, 'neces': -1.7, 'necess': -0.5,
}
PERSON = {'i', 'you', 'he', 'she', 'it', 'we', 'they', 'who'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    start = (prefix.position == 0 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    prev = '' if start else prefix.token_strings[-2].strip().lower()
    value = VERBS.get(word, RELATED.get(word, TRANSLATIONS.get(word, 0.0)))
    if '需要' in word and word != '需要':
        value = -1.9
    elif '需求' in word:
        value = -1.0

    if word == 'need':
        if prev in {'the', 'no'}:
            value += 1.35
        elif prev in {'a', 'an'}:
            value += 0.6
        elif prev in {'you', 'they'}:
            value -= 0.65
        elif prev in {'i', 'we', 'who'}:
            value -= 0.25
        elif prev in {"'ll", '’ll', "'d", '’d', 'really'}:
            value -= 1.2
    elif word == 'needs':
        if prev in PERSON or prev == 'there':
            value -= 0.65
        elif prev in {'the', 'a', 'an', 'no'}:
            value += 0.4
    elif word == 'needed':
        if prev in PERSON:
            value -= 0.85
        elif prev in {'is', 'are', 'as', 'the', 'not'}:
            value += 0.4
    elif word == 'want':
        if prev in {'i', 'you', 'they', 'who', 'would'}:
            value -= 0.2
        elif prev in {'just', 'also', 'to', 'might'}:
            value += 0.5
    elif word in {'have', 'has', 'had'}:
        if prev in PERSON - {'we'}:
            value -= 0.13
        elif prev in {'which', 'to', 'and', ','}:
            value += 0.1
        elif prev in {'there', 'already'}:
            value -= 0.4
    elif word == 'like':
        if prev in {'would', "'d", '’d'}:
            value = -0.95
        elif prev in PERSON:
            value = -0.4
        elif prev in {"'t", '’t', 'really', 'also'}:
            value = -0.3

    if value == 0.0 and not start and token.isalpha():
        value = 0.65 * VERBS.get(prev + word, 0.0)
    if word == 'need' and token.strip() == 'Need':
        value -= 0.35
    if word in {'has', 'had', 'having'} and token.strip()[:1].isupper():
        value += 0.2
    if token.startswith('\t'):
        value *= 0.65
    if start:
        value *= 0.55
    return None, float(value)

programs.luna:
"""A small lexical rule for the component's strongest negative responses."""

READS: tuple[str, ...] = ()

BASELINE = -0.00775
HAVE_FORMS = {"have": -0.93, "has": -0.78, "had": -0.87}
WANT_NEED_FORMS = {
    "want": -2.55,
    "need": -6.37,
    "needed": -4.37,
}
NECESSITY_WORDS = {"necessary": -1.04, "的需求": -0.85}
SEEM_FORMS = {"seemed": -0.63}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()

    if word in HAVE_FORMS:
        value = HAVE_FORMS[word]
    elif word in WANT_NEED_FORMS:
        value = WANT_NEED_FORMS[word]
    elif word in NECESSITY_WORDS:
        value = NECESSITY_WORDS[word]
    elif word in SEEM_FORMS:
        value = SEEM_FORMS[word]
    elif word == "like" and len(prefix) > 1:
        previous = prefix.token_strings[-2].strip().casefold()
        value = -0.72 if previous == "would" else BASELINE
    elif word == "我要":
        value = -0.39
    elif word == "내":
        value = -1.05
    else:
        value = BASELINE

    return None, float(value)

programs.sol:
"""English topic-introducing phrases, especially 'talk(ing) about'.

Predict a large negative pulse on 'about' after talking, smaller ones after
speaking, writing, thinking, asking, or rhetorical 'what'. Mark related
speech verbs, especially infinitives/promises, and two action collocations.
This captures the rare large responses, not the diffuse lexical background.
Keep six nonblank tokens of history, resetting at each document boundary.
"""
READS = ()
TALK = {'talk': -1.20, 'talking': -1.42, 'talks': -0.94, 'talked': -1.04}
SPEAK = {'speak', 'speaking', 'speaks', 'spoke', 'spoken'}
WRITE = {'write', 'writing', 'writes', 'wrote', 'written', 'blog', 'blogging'}
THINK = {'think', 'thinking', 'thinks', 'thought'}
ASK = {'ask', 'asks', 'asking', 'asked', 'inquire', 'discussion'}
SAY = {'say', 'says', 'said', 'saying', 'tell', 'telling', 'told'}
TOPIC_VERBS = set(TALK) | SPEAK | WRITE
CUES = {'to', 'will', "'ll", '’ll', 'please', 'you', 'we', 'i'}
# Response on a speech verb: ordinary use, then personal/infinitive use.
ACTIONS = {
    'discuss': (-0.13, -0.28),
    'explain': (-0.04, -0.26),
    'show': (0.07, -0.15),
    'suggest': (0.03, -0.26),
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    history = () if carry is None or carry[0] != doc else carry[1]
    word = prefix.token_strings[-1].strip().lower()
    prev = history[-1] if history else ''
    before = history[-2] if len(history) > 1 else ''
    value = 0.0
    if word == 'about':
        value = -0.09
        if prev in TALK:
            value = TALK[prev]
        elif prev in SPEAK:
            value = -0.78
        elif prev in WRITE:
            value = -0.73
        elif prev in THINK or prev in ASK:
            value = -0.29
        elif prev in SAY:
            value = -0.35
        elif prev == 'what':
            value = -0.39
        elif any(w in TOPIC_VERBS for w in history):
            value = -0.62
    elif word == 'of':
        if prev in TALK or prev in SPEAK:
            value = -0.50
        elif prev in THINK:
            value = -0.14
    elif word == 'talk':
        value = -0.33 if prev == 'to' else -0.18
    elif word == 'talking':
        value = -0.19
    elif word in ACTIONS:
        value = ACTIONS[word][prev in CUES]
        if prev == 'to' and before == 'going':
            value = -0.49 if word == 'show' else -0.40
        elif word == 'explain' and prev in {'will', "'ll", '’ll'}:
            value -= 0.15 if before == 'i' else 0.0
    elif word == 'discussion':
        value = -0.10
    elif word == 'able' and prev in {'be', 'being', 'been'}:
        value = -0.22
    elif word == 'away' and prev in {'take', 'takes', 'took', 'taken'}:
        value = -0.50 if prev == 'take' else -0.34
    if word:
        history = (history + (word,))[-6:]
    return (doc, history), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:5255, a mostly token-driven component.

What it does: it is strongly negative on "about" when it follows a verb of talking
or discussing ("talk about", "talking about", "talks about", "discuss ..."), the
clearest and largest response in the data (about -1.2 to -1.4). It is weakly
negative on "about" after thinking or asking verbs ("think about", "know about"),
and on other "about" and "of" phrases, and on the talk/discuss/explain words
themselves. It is weakly positive on the "try" family ("trying", "tried") and on
"kind" (as in "kind of"). Everything else is predicted as 0.

The program is a small set of word classes plus one context rule. It captures
only a small part of the component's variance; the rest is spread over many
individual words.
"""

READS = ()

# Verbs of talking or discussing: "about" after one of these is the strong case.
TALK_VERBS = {"talk", "talks", "talking", "talked", "discuss", "discussing", "discussed"}
# Verbs of thinking, knowing or asking: "about" after these is a weaker case.
THINK_VERBS = {"think", "thinking", "thought", "know", "ask", "asking", "asked", "learn",
               "heard", "worried", "concerned", "excited"}
# The "try" family, and "kind" as in "kind of".
TRY_WORDS = {"try", "trying", "tried", "tries"}
KIND_WORDS = {"kind"}
# Words that themselves tend to come out weakly negative.
NEG_WORDS = {"talk", "discuss", "discussing", "discussion", "explain", "able", "pretty",
             "little", "links"}


def _word(s):
    return s.strip()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""

    if word in ("about", "About"):
        if prev in TALK_VERBS:
            value = -1.2
        elif prev in THINK_VERBS:
            value = -0.2
        else:
            value = -0.1
    elif word in KIND_WORDS:
        value = 0.2
    elif word in TRY_WORDS:
        value = 0.1
    elif word in NEG_WORDS:
        value = -0.1
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate a comma-separator response, strongest after numbers or in lists.

Digit adjacency, nearby/frequent commas, and short preceding words strengthen
standalone commas. A diminishing opening-context term handles their larger
responses near a document's start. Periods, line endings, closing brackets,
colons, semicolons, and East Asian punctuation have separate opening responses.
Small rules cover whitespace, opening digits, hash markers, and negative user
role labels. Other tokens predict zero. All state resets between documents.
"""
import math

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        age, previous, before_previous = 0, '', ''
        last_comma, commas, word_length, seen_newline = -1000, 0, 0, False
    else:
        (_, age, previous, before_previous, last_comma, commas,
         word_length, seen_newline) = carry
    digit = bool(previous) and previous[-1].isdigit()
    second_digit = before_previous.strip().isdigit()
    short_word = word_length <= 1
    opening = math.exp(-age / 12.0)
    value = 0.0

    if token == ',':
        value = (0.023 + 0.352 * digit + 0.126 * second_digit
                 + 1.626 / (age + 1)**0.813
                 + 0.266 * digit * math.exp(-age / 39.3)
                 + 0.773 * math.exp(-(age - last_comma) / 3.26)
                 - 0.057 * math.log1p(word_length)
                 + 0.833 * commas / max(age, 1))
        if age == 0:
            value = 1.879
    elif token == '.':
        value = (-0.027 + 0.472 * math.exp(-age / 13.9)
                 + 0.036 * short_word + 0.015 * digit)
        if age == 0:
            value = 0.956
    elif token == '\n':
        value = (-0.022 + 0.258 * opening
                 + 0.302 * math.exp(-age / 9.56) * (not seen_newline)
                 + 0.031 * (len(previous.strip()) <= 1))
    elif token in ('.\n', '.\n\n'):
        value = (-0.006 + 0.501 * math.exp(-age / 10)
                 + 0.163 * math.exp(-age / 25.9) + 0.019 * digit)
        if age == 0:
            value = 0.63 if token == '.\n' else 0.34
    elif token == '\n\n':
        value = -0.022 + 0.45 * math.exp(-age / 9)
        if age == 0:
            value = 0.285
    elif token in ('，', '、'):
        value = -0.056 + 0.139 * digit + 0.65 * opening
        if age == 0:
            value = 1.21 if token == '，' else 0.4
    elif ',' in token and not any(c.isalnum() for c in token):
        value = (-0.096 + 0.451 * math.exp(-age / 7.1)
                 + 0.05 * math.exp(-age / 61) + 0.12 * digit)
    elif token.startswith((')', ']', '}')) and not any(
            c.isalnum() for c in token):
        value = -0.026 + 0.308 * opening + digit * (0.031 + 0.087 * opening)
        if age == 0:
            value += 0.104
    elif ('。' in token or '．' in token) and not token.strip('。．\n\r'):
        value = 0.012 + 0.715 * math.exp(-age / 7)
    elif token.startswith((':', ';')) and not any(c.isalnum() for c in token):
        value = -0.038 + 0.097 * opening + digit * (0.052 + 0.206 * opening)
        if age == 0:
            value += 0.311
    elif token.isspace():
        value = -0.012 + 0.081 * opening + 0.04 * digit * opening
        if age == 0:
            value = -0.056
    elif token.strip().isdigit():
        value = 0.493 if age == 0 else -0.005 + 0.13 * opening
    elif token.startswith('#'):
        value = 0.04 + 0.5 * opening
    elif token == 'user' and previous == '<|im_start|>':
        value = -0.097 - 0.340 * math.exp(-age / 33.7)

    if token == ',':
        last_comma, commas = age, commas + 1
    for character in token:
        if character.isalnum() or character == '_':
            word_length += 1
        else:
            word_length = 0
    return (doc, age + 1, token, previous, last_comma, commas,
            word_length, seen_newline or '\n' in token), float(value)

programs.haiku:
"""German finite auxiliaries and modals, and personal pronouns, in German text.

The component reads only the current token. It is a German-verb-and-pronoun detector:
  - finite forms of the auxiliaries and modals (ist, wird, hat, war, soll, kann, sind,
    werden, habe, wollte) and the subject pronouns er, ich, wir, sie, Sie: about 3.5;
  - es, man, sich, mich, mir, ihn, ihm, uns, du, dich: about 3;
  - a few weaker German words (ob, wo, da, gibt, sagte, lassen, ihr, ...): about 2;
  - linking words (und, um, das, der, den, die, daß, dass, zu): about 0.7;
  - everything else: 0.
The word counts only in German text. The step keeps the German-cue flags of the last
WINDOW (48) tokens of the same document, and the word scores only if at least two of them
are common German function words (der, die, das, und, nicht, ich, mit, auf, ...). So the
same spellings in English, Spanish, Polish or French (is, was, he, es = "is") stay at 0.
"""
READS = ()

WINDOW = 48
GERMAN_CUES = {" der", " die", " das", " und", " nicht", " ein", " eine", " mit", " auf",
               " ist", " sich", " auch", " zu", " den", " dem", " des", " von", " im",
               " ich", " sie", " er", " dass", " daß", " wir", " sind", " oder"}
AUX_VERBS = {"bin", "bist", "ist", "sind", "seid", "war", "warst", "waren", "wart",
             "habe", "hast", "hat", "haben", "habt", "hatte", "hattest", "hatten", "hattet",
             "werde", "wirst", "wird", "werden", "werdet", "wurde", "wurdest", "wurden",
             "kann", "kannst", "können", "konnte", "konnten", "könnte", "könnten",
             "soll", "sollst", "sollen", "sollte", "sollten", "muss", "musst", "müssen",
             "musste", "mussten", "will", "willst", "wollen", "wollte", "wollten",
             "darf", "darfst", "dürfen", "durfte", "möchte", "mag", "würde", "würden",
             "wäre", "wären", "hätte", "hätten"}
SUBJECT_PRONOUNS = {"er", "ich", "wir", "sie", "Sie"}
OTHER_PRONOUNS = {"es", "man", "sich", "mich", "mir", "ihn", "ihm", "uns", "du", "dich"}
LINKING_WORDS = {"und", "um", "das", "der", "den", "die", "daß", "dass", "zu"}
MORE_WORDS = {"gibt", "gab", "sei", "sagte", "lassen", "ob", "wo", "da", "wer", "ihr"}


def word(token):
    """The token as a lowercase word, or None if it is not the start of a word."""
    if token[:1] == " " or token[:1].isupper():
        return token.strip().lower()
    return None


def value(token):
    """How strongly one token's activation leans positive, before the German gate."""
    w = word(token)
    if w is None:
        return 0.0
    if w in AUX_VERBS:
        return 3.5
    if w in SUBJECT_PRONOUNS:
        return 3.5
    if w in OTHER_PRONOUNS:
        return 3.0
    if w in MORE_WORDS:
        return 2.0
    if w in LINKING_WORDS:
        return 0.7
    return 0.0


def step(carry, prefix, upstream):
    """Carry: (document id, German-cue flags of the last WINDOW tokens)."""
    doc = prefix.document_ids[-1]
    flags = [] if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    flags = (flags + [token in GERMAN_CUES])[-WINDOW:]
    german = sum(flags) >= 2
    return (doc, flags), (value(token) if german else 0.0)

programs.sol:
"""Respond negatively to single underscores emitted as punctuation.

Underscores inside word tokens and long underline runs do not trigger this
rule. Braced subscripts and trailing punctuation weaken the response;
NAME placeholders strengthen it, while mathematical variables weaken it.
Repeated underscore punctuation gradually reduces the negative response.
Double underscores receive a small positive value; other tokens receive zero.
"""
import math

READS = ()
GREEK = frozenset('''
alpha beta gamma delta epsilon zeta eta theta iota kappa lambda mu nu xi
omicron pi rho sigma tau upsilon phi chi psi omega
'''.split())
BINDERS = frozenset('def function class var let const namespace for in'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    count = carry[1] if carry is not None and carry[0] == doc else 0
    s = prefix.token_strings[-1]
    initial = len(prefix.token_strings) == 1 or prefix.document_ids[-2] != doc
    prev = ''
    if not initial:
        prev = prefix.token_strings[-2].strip()
    state = (doc, count)
    if s.strip() == '__':
        return state, 0.36 if s.startswith(' ') else 0.18
    if s.count('_') != 1 or any(c.isalnum() for c in s):
        return state, 0.0

    left, right = s.split('_')
    if right.startswith(('{', '\\', '^')):
        value = -1.0 if '}' in left else -0.66
    elif '\n' in right:
        value = -1.24
    elif right.startswith(','):
        value = -1.96
    elif right.startswith(('.', ';', ':')):
        value = -1.49
    elif right:
        value = -1.2
    elif left.isspace():
        value = -2.52
        if prev in BINDERS:
            value -= 0.55
        elif prev.lower() in GREEK:
            value += 0.76
    elif left:
        value = -2.65
        if '/' in left:
            value -= 1.15
        if '.' in left:
            value -= 0.3
        if any(c in left for c in '})]'):
            value += 0.45
        if '(' in left:
            value -= 0.3
        if left.startswith(' '):
            value -= 0.24
    else:
        value = -3.13
        variable = prev.strip('($,')
        if prev == 'NAME':
            spaced = prefix.token_strings[-2].startswith(' ')
            value = -4.24 if spaced else -3.90
        elif len(variable) == 1 and variable.isascii() and variable.isalpha():
            value += 0.58
        elif prev.lower() in GREEK:
            value += 0.76
        elif prev.isdigit():
            value += 0.45
        elif prev and all(c in '})]' for c in prev):
            value += 0.95
    if s in ('_', ' _') and prev and set(prev) == {'_'}:
        value += 0.35
    if initial and s == '_':
        value = -2.26
    else:
        value *= 1.07 - 0.045 * math.log1p(min(count, 32))
    return (doc, count + 1), float(value)

programs.haiku:
"""Village and rural-life words: the component layers.0.mlp.down_proj:5259.

A token-level detector for villages, the countryside, farming people and small towns. Its
output depends on the current token alone: the program names the concept each token belongs
to and returns that concept's measured strength, and 0 for every other token. The strongest
responses are to the word "village" (about 3.9; the Chinese character 村, village, about
6.8), with rural areas and peasants next (about 1 to 3), then towns and townships, poverty
relief, and a weaker tail of farming, county and residential-community words.

Values are the average activation on that token in training text (a few tenths to about 7).
Everything not listed gives 0; the rest of the variance is small, context-dependent noise.
"""

READS = ()

# Villages and villagers
VILLAGE = {"village": 3.9, "villages": 3.3, "villager": 3.3, "villagers": 3.3, "vill": 0.9}
# The countryside, rural life and farming people
RURAL = {
    "rural": 1.9, "countryside": 1.0, "rustic": 1.1,
    "peasant": 1.3, "peasants": 2.1, "farmer": 0.9, "farmers": 1.2,
