"""Layer-0 MLP unit 5261: a detector for game, GUI and user-input code.

The unit goes negative on words from game and graphical-interface programming, and most
strongly on method calls into graphics and game libraries (pygame, Turtle, .display, .Clock,
.setBounds, .choice). It is weaker on the nouns of games and interfaces (game, score, screen,
label), on user-input and random-choice words (input, choice, random, scanf), and on the
while/elif of menu loops. It is slightly positive on Java and enterprise API names (.println,
.view, resultSet). Elsewhere it is about zero. The value is a fixed table over word classes,
each set to roughly the average activation the unit shows on that class.
"""
import re

READS = ()

LIBRARY_CALLS = {"display", "clock", "setbounds", "choice", "time", "fill", "rect", "pack", "mainloop", "random", "randint", "sprite", "addeventlistener", "getinput", "quit", "exit"}
LIBRARIES = {"pygame", "turtle", "jlabel", "jframe", "jbutton"}
GAME_GUI_NOUNS = {"game", "score", "screen", "label", "sprite", "menu", "keyboard", "snake", "enemy", "paddle", "quiz", "welcome"}
INPUT_WORDS = {"input", "choice", "random", "enter", "scanf", "stdin", "readline", "prompt"}
CONTROL = {"while", "elif"}
ENTERPRISE = {"println", "view", "resultset", "shoppingcart", "cartitem", "printstacktrace", "getparameter", "getattribute", "hibernate", "springframework", "lombok", "tempfile", "chmod", "usermodel", "permission", "viewmodel"}

def word(token):
    """The token's word: leading dots, spaces and brackets dropped, lower-cased."""
    return re.sub(r"^[^A-Za-z]+", "", token).lower()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    w = word(token)
    if w in LIBRARIES or (token.startswith(".") and w in LIBRARY_CALLS):
        value = -0.8
    elif w in GAME_GUI_NOUNS or w in INPUT_WORDS:
        value = -0.23
    elif w in CONTROL:
        value = -0.18
    elif w in ENTERPRISE:
        value = 0.07
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate a re-/again spelling detector.

A separate 'Re' is strongest; 're' is weaker inside a word. Longer re-
words respond less, with an extra response for redoing/changing actions.
Common lookalikes such as read and real are excluded. Words for again,
back, return and repetition in several languages also respond, as does
a standalone carriage return. A split re-word briefly echoes on its
next fragment, especially the colon in Re:. This is a spelling-based
approximation, not a test of whether the sentence describes repetition.
"""
import re

READS = ()

LOOKALIKES = (
    "read", "ready", "real", "reason", "relat", "relig", "region",
    "regular", "remov", "remain", "resour", "represent", "respectiv",
    "render", "rend", "rent", "restaur", "recommend", "register",
)
REDO = (
    "rebuild", "rebuilt", "recon", "reform", "revis", "revert", "reuse",
    "reopen", "recreat", "recharg", "reboot", "reunit", "reunion",
    "reprint", "reassign", "reaffirm", "rejoin", "rejuven", "reorg",
    "reinst", "reint", "reclaim", "replay", "retry",
)
RESPONSE = ("react", "replac", "repeat", "reproduc", "reject")
ABBREVIATIONS = {"ref", "rev", "rep", "rec", "repl", "repr"}
AGAIN = {
    "again", "back", "feedback", "wieder", "encore", "lại", "nữa",
    "やはり", "再び",
}
RETURN = {"zurück", "rück", "还", "還", "返", "回", "復", "重", "反"}
REPETITION = {"再次", "重复", "恢复", "回复", "反复", "再度", "다시"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, echo, was_bare = "", 0.0, False
    else:
        _, previous, echo, was_bare = carry
    text = prefix.token_strings[-1]
    word = re.sub(r"^[\W_]+", "", text)
    lower = word.lower()
    boundary = text != word or not previous[-1:].isalpha()
    bare = lower == "re"
    value = 0.0

    if bare:
        if text.startswith(("'", "’")):
            value = 0.1  # 'are' contraction rather than the prefix
        elif word == "Re":
            value = 3.5 if text.startswith(".") else 6.0
        elif word == "RE":
            value = 2.8 if boundary else 1.2
        else:
            value = 3.9 if boundary else 1.1
    elif lower.startswith("re"):
        if lower.startswith(LOOKALIKES):
            value = 0.0
        elif lower.startswith(REDO):
            value = 2.2
        elif lower.startswith(RESPONSE):
            value = 1.6
        elif lower in ABBREVIATIONS:
            value = 1.9 if word[0].isupper() else 1.6 if boundary else 1.0
        elif lower.startswith(("return", "review")):
            value = 0.95
        elif len(word) <= 4:
            value = 0.75 if boundary or word[0].isupper() else 0.35
        else:
            value = 0.7
    elif lower in AGAIN:
        value = 0.85
    elif lower in RETURN:
        value = 1.3
    elif word in {"再", "重新"}:
        value = 3.4
    elif word in {"재", "复"}:
        value = 2.3
    elif word in REPETITION:
        value = 1.8
    elif lower.startswith("ré"):
        value = 1.25 if len(lower) == 2 else 0.5
    elif text == "\r":
        value = 0.95

    next_echo = value if lower.startswith("re") and value > 0.5 else 0.0
    if echo and text and not text[0].isspace():
        if was_bare and text.startswith(":"):
            value += 0.3 * echo
        elif any(c.isalpha() for c in text):
            value += 0.12 * echo
    return (doc, text, next_echo, bare), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 5262: a "re-" detector.

It reads only the current token. It fires when that token is a word, or the
start of a word or identifier segment (after a space, "_", "/", "-" or "."),
spelled "re": Re, re, ref, rep, rec, rev, require, return, release, ...
The bare piece "re" is the strongest (also as "_re", "/re", "-re").
Tokens meaning "again / back / return / repeat" get a medium value, in English
or another language (again, back, wieder, zurück, 再, 复, 還, 回, 反, 又, lại).
Everything else is 0. The sizes are rough means from sampled text, not fitted
to the eval rows.
"""

READS = ()

# Words and characters with the "again / back / return / repeat" sense of "re-".
AGAIN_SENSE = frozenset({
    "again", "back", "return", "returns", "returned", "returning", "repeat",
    "repeated", "restore", "restored", "retry", "result",
    "wieder", "zurück", "再", "复", "復", "還", "还", "回", "反", "返", "又", "lại", "nữa",
})


def activation(token):
    # Drop a leading space or identifier separator, so "_replace" reads as "replace".
    word = token.strip().lower().lstrip("_/-.")
    if word == "re":
        return 3.0
    if word in AGAIN_SENSE:
        return 0.9
    if word.startswith("re"):
        return 1.0 if len(word) <= 4 else 0.7
    return 0.0


def step(carry, prefix, upstream):
    return carry, float(activation(prefix.token_strings[-1]))


if __name__ == "__main__":
    for tok in ["Re", " re", "_re", " ref", "_replace", " return", " again", " 再", " read", " of"]:
        print(repr(tok), activation(tok))

programs.sol:
"""A context-sensitive response to the beginning of a decimal number.

Five through nine give increasingly positive responses. A following digit
is quiet, and a digit after a decimal point is much weaker. Commas and a
preceding number separated by whitespace also weaken the response.
Written-out English and Chinese numbers give smaller, signed responses.
These rules summarize training examples; small activations on ordinary
text are intentionally left at zero. Only two preceding tokens and a short
text tail (for hexadecimal escapes) are remembered, reset per document.
"""
import unicodedata

READS = ()

# Entries are ordered by the numerical value of a digit, zero through nine.
LEADING = (0.03, 0.01, 0.01, 0.01, 0.14, 0.75, 1.17, 1.41, 1.73, 2.08)
CONTINUING = (-0.01, -0.01, 0.06, 0.01, -0.14,
              0.03, -0.03, 0.0, -0.02, -0.08)
DECIMAL = (-0.03, -0.05, -0.10, -0.17, -0.27,
           0.04, 0.13, 0.22, 0.29, 0.37)
NUMBER_WORDS = {
    'three': -0.16, 'four': -0.24, 'five': 0.17, 'six': 0.33,
    'seven': 0.47, 'eight': 0.63, 'nine': 0.91,
    'third': -0.03, 'fourth': -0.17, 'fifth': 0.24, 'sixth': 0.38,
    'seventh': 0.50, 'eighth': 0.66, 'ninth': 0.82,
    'fifty': 0.20, 'sixty': 0.40, 'seventy': 0.66,
    'eighty': 0.79, 'ninety': 0.62,
}
CHINESE_NUMBERS = {
    '二': -0.25, '三': -0.20, '四': -0.33, '五': 0.12,
    '六': 0.18, '七': 0.35, '八': 0.45, '九': 0.51,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, tail = '', '', ''
    else:
        _, previous, before, tail = carry
    value = 0.0
    if len(token) == 1 and token.isdecimal():
        digit = unicodedata.decimal(token)
        value = LEADING[digit]
        if not previous:
            value = 0.0
        elif previous[-1:].isdigit():
            value = CONTINUING[digit]
        elif previous.endswith('.'):
            if before[-1:].isdigit():
                value = DECIMAL[digit]
            else:
                value *= 0.70
        elif previous.endswith(','):
            if before[-1:].isdigit():
                value = 0.47 * value if digit >= 5 else -0.07
            else:
                value *= 0.85
        elif tail.endswith('\\x'):
            value *= 0.2
        elif len(tail) >= 3 and tail[-3:-1] == '\\x':
            value = CONTINUING[digit]
        elif previous.isspace() and before[-1:].isdigit():
            value *= 0.58
            if digit == 4:
                value = 0.0
        elif not previous.isspace() and not previous.endswith(('(', '[')):
            value *= 0.90
    else:
        word = token.strip()
        value = NUMBER_WORDS.get(word.lower(), CHINESE_NUMBERS.get(word, 0.0))
        if value > 0 and word.lower() in NUMBER_WORDS:
            if not token.startswith(' ') or not word.islower():
                value *= 0.5
    return (doc, token, previous, (tail + token)[-8:]), float(value)

"""A character-joining response, strongest for fragmented CJK characters.

A token decoded alone as a replacement character can finish the incomplete
UTF-8 character before it. Predict a negative response using that character's
script and the preceding fragment's spacing. Recent kana distinguishes
Japanese context. Separate Thai tone/vowel signs also get negative responses;
ordinary text stays near zero. No token-ID lookup is used.
"""
import unicodedata

READS = ()
THAI_TONE_MARKS = frozenset("่้๊๋")


def completed_character(c, previous, started, japanese):
    n = ord(c)
    spaced = previous.startswith(" ")
    continuation = previous == "�" and not started
    lead = previous.endswith("�") and started and not spaced
    if 0x3400 <= n <= 0x4dbf or 0x4e00 <= n <= 0x9fff:
        if lead:
            return -2.46 if japanese else -2.05
        if continuation:
            return -0.63 if japanese else -0.50
        return -0.44
    if 0xac00 <= n <= 0xd7af:
        return -0.64 if continuation else -1.12
    if 0x3040 <= n <= 0x30ff:
        return -0.06 if spaced else -0.30
    if 0x0e00 <= n <= 0x0e7f:
        return -0.92
    if 0x0370 <= n <= 0x03ff:
        return -0.26 if spaced else -0.96
    if 0x0400 <= n <= 0x052f:
        return -0.60 if spaced else -0.96
    if 0x0900 <= n <= 0x0dff:
        return 0.0 if spaced else -0.28
    category = unicodedata.category(c)
    if category == "Sm":
        return -0.75 if lead else -0.18
    if category.startswith("P"):
        return -0.32 if spaced else -0.52
    if category.startswith("L"):
        return -0.96 if lead else -0.42 if continuation else -0.73
    return -0.75 if lead else -0.45


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, False, False, "", 1000)
    # Flags describe the previous token: unfinished, and newly started.
    _, pending, started, previous, kana_age = carry
    token = prefix.token_strings[-1]
    incomplete = False
    value = -0.001
    if "�" in token:
        last = prefix.text_prefixes[-1][-1:]
        incomplete = last == "�"
        if token == "�":
            if not incomplete and last:
                value = completed_character(last, previous, started,
                                            kana_age < 32)
            elif pending:
                value = 0.13 if previous.startswith(" ") else -0.44
            else:
                value = 0.05
        elif incomplete:
            value = 0.05
    elif token and all("\u0e00" <= c <= "\u0e7f" for c in token):
        if token in THAI_TONE_MARKS:
            value = -0.83
        elif token == "์":  # Thai cancellation mark
            value = -0.59
        elif unicodedata.category(token[0]) == "Mn":
            value = -0.25
    if any("\u3040" <= c <= "\u30ff" for c in token):
        kana_age = 0
    else:
        kana_age = min(1000, kana_age + 1)
    # A fragment starts a character when its predecessor was complete.
    return (document, incomplete, not pending, token, kana_age), float(value)

programs.luna:
"""Mark byte fragments that cannot decode alone, especially in East Asian text."""

READS = ()


def is_east_asian(char):
    code = ord(char)
    return (
        0x3040 <= code <= 0x30FF
        or 0x3400 <= code <= 0x9FFF
        or 0xAC00 <= code <= 0xD7AF
        or 0x0E00 <= code <= 0x0E7F
    )


def step(carry, prefix, upstream):
    if prefix.token_strings[-1] != "\ufffd":
        return None, 0.0

    current_doc = prefix.document_ids[-1]
    recent = []
    for i in range(len(prefix.token_strings) - 2, max(-1, len(prefix.token_strings) - 6), -1):
        if prefix.document_ids[i] != current_doc:
            break
        recent.append(prefix.token_strings[i])

    if any(is_east_asian(char) for token in recent for char in token):
        return None, -1.0
    return None, -0.1

programs.sol:
"""A negative lexical signal for firms and enterprises, especially Chinese 企业.

Recognize business-organization words and a few institutional terms in the
current token, including enterprise word fragments. Enterprise words are
stronger than ordinary company words;
plurals and capitalization sometimes change the strength. Chinese enterprise
compounds retain a strong response. Unrecognized tokens receive zero.

This describes the main large responses, not the many weak token-specific
responses or their context-dependent variation.
"""
READS = ()

# Related business words and translations share approximate response strengths.
WORD_GROUPS = (
    (-2.7, {'enterprise', 'enterprises', 'corporate'}),
    (-1.5, {'firms', 'unternehmen', 'entreprises', 'предприятия', 'предпри'}),
    (-1.3, {'companies', 'corporations', 'الشركات'}),
    (-1.2, {'firm', 'empresa', 'empres', 'entreprise', 'メーカー', 'メーカ'}),
    (-1.7, {'empresas'}),
    (-0.9, {'employers'}),
    (-0.7, {'businesses', 'employer'}),
    (-0.5, {'corporation', 'бизнес'}),
    (-0.38, {'manufacturer', 'manufacturers', 'компания', 'компании'}),
    (-0.3, {'organizations', 'organisations'}),
    (-0.18, {
        'business', 'industry', 'industries', 'industrial', 'manufacturing',
    }),
)
WORDS = {word: value for value, group in WORD_GROUPS for word in group}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip()
    lower = word.lstrip('./\\').lower()
    value = 0.0
    # 企: enterprise root; 企业 / 企業: simplified / traditional spelling.
    if word == '企':
        value = -5.9
    elif word == '企业':
        value = -5.1
    elif word == '企業':
        value = -4.2
    elif '企业家' in word:
        value = -2.3
    elif '企业' in word:
        value = -4.2 if word.endswith('企业') else -4.0
    # State-owned firms, then property, auto, central-state and private firms.
    elif word == '国企':
        value = -4.5
    elif word in {'房企', '车企', '央企', '民企'}:
        value = -3.2
    elif word == '기업':
        value = -3.2
    # Chinese company, group and work-unit vocabulary.
    elif '公司' in word or word in {'集团', '单位', '單位'}:
        value = -0.55
    # Public-service organizations and colleges.
    elif word == '事业单位':
        value = -2.4
    elif word in {'高校', '院校'}:
        value = -1.5
    elif lower == 'company':
        value = -0.36 if word == 'Company' else -0.98
        if word.isupper():
            value = -0.5
    elif word == 'org' and raw.startswith(' '):
        value = -0.32
    elif lower in WORDS:
        value = WORDS[lower]
    return None, value

"""Detect string-like spellings and related text vocabulary.

The main positive signal is 'string', in prose or code. Its plural,
abbreviation, suffix compounds and familiar string operations are weaker.
Text fields, types, collections and locations get small positive values;
a few non-string types get small negatives. Complete Chinese string words
and a Russian string-related fragment are also recognized.

Case and leading code punctuation adjust strength. The last 80 characters,
reset at document boundaries, distinguish word fragments and boost imports,
C++ includes, type annotations and public/private declarations. These rules
approximate lexical responses; they are not a parser or a token-id table.
"""
import re

READS = ()
LEADING_SEPARATORS = re.compile(r'^[\W_]+')
STRING_OPERATIONS = {
    'stringify', 'substring', 'substr', 'stringbuilder', 'stringutils',
    'stringvalue', 'strcpy', 'strcmp', 'strconv', 'sprintf', 'strlen',
}
FIELD_WORDS = {'name', 'names', 'text', 'id'}
TYPE_WORDS = {'type', 'bool', 'boolean'}
COLLECTION_WORDS = {'list', 'array', 'arraylist', 'arrays'}
LOCATION_WORDS = {'path', 'url', 'uri', 'dirname', 'filepath', 'urls', 'paths'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    spelling = token.strip()
    word = LEADING_SEPARATORS.sub('', spelling)
    lower = word.lower()
    separator = spelling[:1] if spelling != word else ''
    fragment = token == word and bool(tail) and tail[-1].isalpha()
    value = 0.0

    if lower == 'string':
        value = 6.1 if token == 'string' else 5.6
        if word == 'String' and not separator:
            value = 5.8
        if separator in {'(', '<', ','}:
            value = 5.2
        elif separator in {'[', ']'}:
            value = 4.5
        elif separator == '_':
            value = 5.3
        if re.search(r'#\s*include\s*<$|\bimport\s*$', tail):
            value = 7.8
        elif re.search(r'@(var|param|property)\s*$', tail):
            value = 6.6
        elif re.search(r'\b(public|private)(?:\s+final)?\s*$', tail):
            value = 6.6
    elif lower == 'strings':
        value = 4.6
    elif lower == 'str':
        value = 0.8 if fragment else 1.8
        if separator in {'_', '[', '='}:
            value = 2.2
        if word == 'Str' and token.startswith(' '):
            value = 1.0
    elif lower.endswith('string'):
        value = 3.5
    elif lower in STRING_OPERATIONS:
        value = 2.2
    elif lower in FIELD_WORDS:
        value = 0.5 if token.startswith(' ') else 0.65
        if word.isupper():
            value = 0.1 if lower.startswith('name') else 0.35
        if separator in {'_', '.', '-'}:
            value = 0.8
        if lower == 'id' and word == 'id' and fragment:
            value = 0.1
        if (lower == 'text' and tail.endswith('\\') or
                lower == 'name' and tail.endswith('operator')):
            value = 0.05
    elif lower in TYPE_WORDS:
        value = 0.7
    elif lower in COLLECTION_WORDS or lower == 'types':
        value = 0.55
    elif lower in LOCATION_WORDS:
        value = 0.7
    elif lower == 'varchar':
        value = 1.0
    elif lower in {'int', 'long', 'float', 'void'}:
        value = -0.15
    elif lower in {'字符串', '串'}:
        value = 4.2
    elif lower == 'строк':
        value = 2.2

    return (doc, (tail + token)[-80:]), value

programs.haiku:
"""Layer-0 feature for the word "string" in code.

It reads only the newest token and keeps no state. Its activation is a fixed
number per token, chosen by the kind of word the token is:

- the word "string" in any code form ("string", "String", "strings", "_string",
  "<String", "std::string", "tostring"): strong, about 5.5;
- the bare fragment "str" (as in "str(x)", "_str", "(str"): weak, about 1.6;
- common data-type and field-name nouns of programming ("name", "type", "id",
  "list", "path", "url", "text", "bool", "array"): very weak, about 0.5;
- everything else: 0.
