"""Approximate a letter-b cue in short text pieces and across token boundaries.

Short b/B-initial pieces get the strongest response. Certain common complete
English words have weak base cues. 'Be' is weak after a modal or 'to'.
A joined piece after a final b is boosted; repeated b strengthens the cue.
The compound testbed has a strong extra response. Several other scripts'
b-like letters are included. Only the previous token is carried, with a reset
at document boundaries. These rules omit finer word-specific variation.
"""
READS = ()

SUPPRESSED_WORDS = {
    'been', 'being', 'because', 'but', 'by', 'both', 'before', 'between',
    'below', 'back', 'better', 'best', 'became', 'become', 'becomes',
    'begin', 'began', 'beginning', 'bring', 'brought', 'brings', 'beyond',
}
COMMON_B_WORDS = {
    'big', 'book', 'books', 'body', 'build', 'built', 'building', 'black',
}
AUXILIARIES = {
    'to', 'can', 'could', 'will', 'would', 'may', 'might', 'must',
    'should', 'shall', 'cannot',
}
VOWELS = 'aeiouyáéíóúàèìòùäëïöüâêîôûаеёиоуыэюя'
B_LETTERS = 'bBбБبβΒבबব'
B_KANA = 'ばびぶべぼバビブベボ'


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    w = s.lstrip(' \t\n\r_.,/+-*([{\\\'"')
    lower = w.lower()
    n = len(w)
    value = -0.002
    if w and w[0] in 'bB':
        if lower in SUPPRESSED_WORDS:
            strength = 0.0
        elif lower in COMMON_B_WORDS:
            strength = 0.11
        elif w == 'be' and s[:1].isspace():
            strength = -0.03 if previous.strip().lower() in AUXILIARIES else 0.24
        else:
            vowel = n > 1 and lower[1] in VOWELS
            strengths = ((0.61, 0.65, 0.49, 0.37) if vowel
                         else (0.61, 0.33, 0.28, 0.23))
            if n <= 4:
                strength = strengths[n - 1]
            else:
                strength = (0.26 if vowel else 0.20) * (5 / n)**0.5
            if n > 1 and w[0] == 'B':
                strength += 0.04
            if n == 1 and s.startswith(('.', '/', '-')):
                strength += 0.15
        value += strength
        if lower.startswith('bb'):
            value += 0.52
        elif n <= 5 and 'b' in lower[2:]:
            value += 0.21
        if s.lower() == 'bed' and previous.lower().endswith('test'):
            value = 1.32
    elif w and w[0] in 'бБ':
        value += (0.85 if w[0] == 'Б' else 0.57) / n**0.4
    elif w and w[0] == 'ب':
        value += 0.61 / n**0.4
    elif w and w[0] in 'βΒבबব':
        value += 0.17 / n**0.4
    elif w and w[0] in B_KANA:
        value += 0.48 / n**0.4
    elif (w and 0xAC00 <= ord(w[0]) <= 0xD7A3
          and (ord(w[0]) - 0xAC00) // 588 == 7):
        value += 0.30 / n**0.4  # Hangul initial consonant ㅂ.
    elif w.endswith('B') and n <= 4:
        value += 0.21

    if s and previous and previous[-1] in B_LETTERS:
        if s[0].isalpha():
            length = len(s)
            vowel = s[0].lower() in VOWELS
            strengths = (0.92, 0.58, 0.38) if vowel else (0.49, 0.27, 0.22)
            if length <= 3:
                value += strengths[length - 1]
            else:
                value += (0.19 if vowel else 0.04) * (4 / length)**0.5
            if s[0] in 'bBбБ':
                value += 1.01
        elif not s[:1].isspace():
            value += 0.02
        if not s[:1].isspace() and any(c in 'bBбБ' for c in s[1:]):
            value += 0.32
    return (doc, s), float(value)

