"""A lexical -ure detector with a weaker meaning-related response.

The strongest response is to short '-ure' fragments and words such as
measure, figure, sure, structure and texture. A second, weaker response
marks descriptions of form, type, examples and certainty. This is not
an exact tokenizer lookup: case, punctuation and ordinary inflections
share rules. 'For example' and 'health care' are attenuated as idioms.
A few translated counterparts and two formatting markers also respond;
unrecognized tokens predict zero, unless their spelling contains 'ure'.
"""

READS = ()

# These are related word families, not token IDs.
MEASUREMENT = {'measure', 'figure'}
CERTAINTY_TEXTURE = {'sure', 'texture', 'mixture', 'fixture'}
STRUCTURE_SECURITY = {'structure', 'secure', 'procedure', 'capture',
                      'assure', 'cure'}
NATURE_PURITY = {'nature', 'culture', 'picture', 'signature', 'pure',
                'posture', 'adventure', 'ensure'}
LOWER_URE = {'feature', 'future', 'pressure', 'mature', 'venture',
             'literature', 'moisture', 'endure'}
WEAK_URE = {'failure', 'temperature', 'manufacturer', 'exposure',
            'pleasure', 'leisure'}
FORM_CERTAINTY = {
    'type', 'plan', 'similar', 'certain', 'support', 'detail',
    'exercise', 'limit', 'pattern', 'shape', 'guarantee', 'mention',
    'entire', 'usually', 'typically', 'strength', 'technique',
    'promise', 'purity', 'integrity', 'closure', 'frustrated',
}
DESCRIPTION = {
    'instance', 'content', 'context', 'kind', 'determine',
    'characteristic', 'guide', 'bound', 'architecture',
}


def family(word, roots):
    if word in roots:
        return True
    for ending in ('s', 'd', 'ed', 'ing', 'ly'):
        if word.endswith(ending):
            stem = word[:-len(ending)]
            if stem in roots or stem + 'e' in roots:
                return True
    return False


def lexical_value(token, previous):
    word = token.strip().lstrip('._/-').lower()
    if word in {'ure', 'ures', 'ture', 'tures', 'asure', 'asures'}:
        return 3.05
    if word in {'ature', 'atures', 'ured', 'apture', 'ulture',
                'edure', 'cedures'}:
        return 2.25
    if word in {'ura', 'uren', 'uring', 'atura', 'itura', 'uro', 'uras'}:
        return 1.3
    if word in {'measurement', 'measurements', 'assurance'}:
        return 1.3
    if word in {'structural', 'cultural', 'natur', 'uration'}:
        return 0.73
    if word in {'natural', 'naturally', 'security', 'securities'}:
        return 0.08
    if word in {'purely', 'entirely', 'detail', 'detailed'}:
        return 0.3
    if word == 'care':
        return 0.0 if previous.strip().lower() == 'health' else 0.52
    if family(word, MEASUREMENT):
        if word in {'measure', 'measures', 'figure', 'figures'}:
            # A capitalized, spaced Figure is often a numbered illustration.
            if token.startswith(' ') and token.strip() == 'Figure':
                return 2.15
            return 2.8
        return 1.45
    if family(word, CERTAINTY_TEXTURE):
        if word == 'sure':
            return 2.4
        return 2.2 if word in CERTAINTY_TEXTURE or word.endswith('s') else 1.8
    if family(word, STRUCTURE_SECURITY):
        return 1.95 if word in STRUCTURE_SECURITY or word.endswith('s') else 1.3
    if family(word, NATURE_PURITY):
        return 1.45
    if family(word, LOWER_URE):
        return 1.0
    if family(word, WEAK_URE):
        return 0.05
    if word in {'example', 'examples'}:
        return 0.03 if previous.strip().lower() == 'for' else 0.87
    if family(word, FORM_CERTAINTY):
        return 0.75
    if family(word, DESCRIPTION):
        return 0.55
    if word in {'fig', 'typ', 'bound'}:
        return 0.6
    if word in {'sample', 'amount'}:
        return 0.3
    # Translated assurance, purity, example, culture and structure words.
    if word in {'保', '確保', '确保', '保证', '純', '例', '文化', '结构'}:
        return 1.0
    if word in {'тип', 'план', '型', '图', '図'}:
        return 0.7
    if word.startswith('процед'):
        return 1.5
    if 'ure' in word:
        return 0.6
    if token == '<tool_response>':
        return 1.06
    if token == '\t\n':
        return 0.51
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), float(lexical_value(token, previous))

