"""Component layers.0.mlp.down_proj:5269: a word detector for "-ure" words.

It reads the current token and fires on a small family of English words, chiefly those
spelled with "-ure" (sure, figure, measure, structure, culture, nature, pressure,
procedure, feature, ensure, secure, ...): about 1.7 on average, the strongest response.
Weaker responses go to "measuring/ensuring/assurance"-type words, to "type", "kind",
"example" and "instance" (about 0.6), and to a few common nouns and adjectives
(plan, limit, support, future, content, similar, certain: about 0.75).
A chat "<tool_response>" marker gives about 1.05. The "-ure" words that do not fire much
(temperature, exposure, failure, manufacturer, architecture, ...) are listed and scored
near 0. Right after an "-ure" word, " of" also gets a small response (about 0.35).
The program is stateless apart from reading the previous token, and it does not
depend on context otherwise.
"""
import re

READS = ()

URE_WORD = re.compile(r"ure", re.IGNORECASE)
# "-ure" words that do not respond: temperature, exposure, failure, ...
URE_MISS = {"temperature", "temperatures", "exposure", "failure", "failures", "injured",
            "configured", "manufacturer", "manufacturers", "manufactured", "bureau",
            "expenditure", "architecture", "agriculture", "disclosure", "departure"}
ENSURE_WORD = re.compile(r"(ensur|assur|insur|measur)", re.IGNORECASE)
KIND_WORDS = {"type", "types", "kind", "kinds", "example", "examples", "instance", "sort"}
OTHER_WORDS = {"plan", "plans", "feature", "features", "limit", "limits", "support",
               "supports", "future", "content", "context", "similar", "certain",
               "typically", "usually", "mention", "mentions", "details", "pattern"}


def word_value(word):
    if word in URE_MISS:
        return 0.1
    if URE_WORD.search(word):
        return 1.7
    if ENSURE_WORD.search(word):
        return 0.5
    if word in KIND_WORDS:
        return 0.6
    if word in OTHER_WORDS:
        return 0.75
    if word == "<tool_response>":
        return 1.05
    return 0.0


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = word_value(word)
    if prefix.token_strings[-1] == " of" and len(prefix.token_strings) > 1:
        if URE_WORD.search(prefix.token_strings[-2].strip().lower()):
            value = 0.35
    return carry, float(value)

