# Strongest: solve / resolve and their forms.  Medium: solver, solution, resolution, decide.
# Weaker: problem, result, determine, conclude, settle.
SOLVE = re.compile(r"(re)?solv(e|es|ed|er|ers|ing)")
MEDIUM = re.compile(r"(re)?solution\w*|solver\w*|resolution\w*|sol|decid\w*|decision\w*")
WEAK = re.compile(r"problem\w*|result\w*|determin\w*|conclu\w*|settl\w*")
OTHER = {"解决": -7.0, "決": -5.0, "决": -5.0, "quyết": -5.0, "реш": -4.0, "决定": -2.5,
         "判决": -1.0, "化解": -2.4, "问题": -0.8, "問題": -0.8, "结果": -0.9, "結果": -0.9}

