    earlier letter-only tokens it continues."""
    s = prefix.token_strings[-1]
    if s[:1].isspace() or len(prefix.token_strings) < 2:
        return re.sub(r"^\W+", "", s.strip()).lower()
    parts = [s]
    for piece in reversed(prefix.token_strings[:-1]):
        if not piece.isalpha() or len(parts) >= 3:
            break
