"""A document-opening response, strongest on words and code/heading openers.

Reset on each new document, including the beginning of a cropped row.
Estimate its opening token from writing conventions: case, leading spaces,
function words, digits, punctuation, title/question labels and source-file
openers. Most word openings are positive; initial digits, spaces, newlines
and bare opening parentheses are negative. Later tokens get a small decaying
baseline, with separate responses for chat/tool delimiters and initial chat
role labels. This approximation leaves individual lexical variation out.
"""

READS = ()

LOW_OPENING_FUNCTION_WORDS = frozenset('a of in to by was'.split())
NEUTRAL_FUNCTION_WORDS = frozenset(
    'the and for that with from have has had were it you they we as at can will'.split()
)
OPENING_DETERMINERS = frozenset(('The', 'This', 'A', 'An'))
CAPITAL_FUNCTION_WORDS = frozenset(
    'I It We In To At For Is Am Are Can'.split()
)
ROLE_HEADER = {'user': -0.210, 'assistant': -0.140, 'system': -0.337}
QUESTION_STARTS = frozenset(('Q', 'What', 'How', 'Why', 'Question'))
SOURCE_OPENERS = frozenset(('package', 'import', '#include'))
CHAT_MARKERS = {
    '<|im_start|>': 0.042,
    '<|im_end|>': 0.023,
    '<|endoftext|>': -0.017,
    '<think>': 0.023,
    '</think>': 0.079,
    '<tool_call>': 0.053,
    '</tool_call>': 0.019,
    '<tool_response>': -0.109,
    '</tool_response>': 0.060,
}


def opening(s):
    word = s.strip()
    if s == '<|im_start|>':
        return -0.070
    if s.startswith('<|') or s in CHAT_MARKERS:
        return 0.10
    if not word:
        if s in (' ', '\n'):
            return -0.31
        if s == '\t':
            return -0.114
        if s.startswith('\t'):
            return 0.05
        if s == ' ' * len(s):
            return -0.12 if len(s) <= 4 else -0.03
        return -0.10 if '\n\n' in s else -0.05
    if word.isascii() and word.isdigit():
        if word == '0':
            return -0.103
        if word == '2':
            return -0.607
        return -0.33 if word in ('1', '3') else -0.40
    if s == 'Title':
        return 1.85
    if s in SOURCE_OPENERS:
        return 0.55 if s == 'import' else 0.76
    if s in QUESTION_STARTS or s in ('Welcome', 'Use', 'You', 'Your'):
        return 0.66
    if s == 'The':
        return 0.727
    if s == 'This':
        return 0.588
    if s in ('A', 'An'):
        return 0.43
    if word in OPENING_DETERMINERS | CAPITAL_FUNCTION_WORDS and s.startswith(' '):
        return -0.21
    if s.startswith('<?'):
        return 0.44
    if s.startswith('#') or s.startswith('//') or s.startswith('/*'):
        return 0.02 if s.startswith('//') and '\n' in s else 0.40
    if s in ('\\n', '\\t'):
        return -0.06
    if s == '\x00':
        return 0.36
    if word.startswith('(') and s.strip(" ('\"") == '':
        return -0.27
    if s == '.':
        return -0.106
    if s == '`':
        return 0.58
    if word.startswith(('\"', "'", '`', '“', '”')):
        return -0.07 if s.startswith(' ') else 0.20
    if word.startswith('\\\"'):
        return 0.34
    if word == ';':
        return 0.19
    if word.startswith('('):
        return 0.12
    if '\ufffd' in word:
        return 0.20
    if not any(c.isalnum() for c in word):
        return 0.03
    if word in LOW_OPENING_FUNCTION_WORDS and (s.startswith(' ') or word == 'in'):
        return -0.07
    if word in NEUTRAL_FUNCTION_WORDS and (s.startswith(' ') or word == 'the'):
        return 0.02
    if word.isascii() and word.isalpha():
        if s.startswith(' '):
            if word.istitle() or word.isupper():
                return 0.10
            return 0.19 if len(word) > 2 else 0.12
        if word[0].isupper():
            return 0.34
        return 0.18 if len(word) > 2 else 0.11
    return 0.20


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position = 0 if carry is None or carry[0] != doc else carry[1] + 1
    s = prefix.token_strings[-1]
    if position == 0:
        value = opening(s)
    else:
        value = CHAT_MARKERS.get(s, 0.001)
        value += 0.024 / (position + 1) ** 0.65
        if position == 1 and prefix.token_strings[-2] == '<|im_start|>':
            value = ROLE_HEADER.get(s, value)
    return (doc, position), float(value)

