programs.sol:
"""Approximate the component using visible formatting cues.

Training activations concentrate on isolated blanks and explicit separators.
Pure spaces/tabs are stronger at line margins than inside text. At a line
margin, continuing earlier blanks is weaker than starting an indent. Mixed tabs and spaces give a strong
response that decreases with width. Blank-line and nonbreaking-space padding
have smaller responses. Comment/diff markers can also introduce padding.
The end-of-text marker and doubled underscores are separate positive cases.
Ordinary tokens get zero; line state resets at each new document.
"""
READS = ()
LINE_PREFIXES = {'//', '#', '+', '-'}


def horizontal(s, margin, continuing):
    spaces, tabs = s.count(' '), s.count('\t')
    # A string margin is a comment/diff prefix; True is a bare line margin.
    if isinstance(margin, str):
        return 0.35 if margin == '-' and len(s) == 1 else 0.85
    if tabs and spaces:
        # Mixed indentation is stronger than either kind of blank alone.
        return max(1.5, 3.1 - 0.06 * spaces)
    if tabs:
        if margin:
            return 1.55 if continuing else 2.15 - 0.13 * min(tabs - 1, 4)
        return 1.15 if continuing else 0.34 + 0.08 * min(tabs - 1, 3)
    if not margin:
        return 0.10 if continuing else (-0.17 if spaces == 3 else 0.0)
    if continuing:
        return 0.61
    if spaces == 1:
        return 2.97
    if spaces == 2:
        return 2.02
    return 1.6 if spaces < 16 else 1.05


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        margin, continuing = False, False
    else:
        margin, continuing = carry[1:]
    value = 0.0
    if s == '<|endoftext|>':
        value = 1.30
    elif s.endswith('__') and s.count('_') == 2 and not s.strip(' ./()_'):
        value = 1.03
    elif s and not s.strip(' \t'):
        value = horizontal(s, margin, continuing)
    elif s.isspace():
        if '\n' in s or '\r' in s:
            blank = s.strip('\r\n')
            if '\t' in blank and ' ' in blank:
                value = 0.5 * horizontal(blank, margin, continuing)
            elif margin and blank:
                value = 0.75 if '\t' in blank else 0.45
            else:
                value = -0.02 if blank else 0.0
        elif s.strip('\xa0'):
            value = 0.05 if continuing else -0.3
        elif len(s) == 1:
            value = 0.14 if continuing else -0.07
        else:
            value = 0.7 if len(s) < 8 else 0.3
    if '\n' in s or '\r' in s:
        tail = s.replace('\r', '\n').rsplit('\n', 1)[-1]
        margin = not tail.strip()
    elif s.strip():
        margin = s.strip() if margin and s.strip() in LINE_PREFIXES else False
    continuing = bool(s) and s.isspace() and '\n' not in s and '\r' not in s
    return (doc, margin, continuing), float(value)

