"""Indentation detector (layer-0 MLP down_proj, component 5275).

What it responds to: a token made only of spaces and/or tabs, with no line break, i.e. an
indentation or alignment run. Strength depends on where it sits:
  - at the start of a line (the token before ends in a line break): strongest;
  - mixed tab-and-space runs: strong anywhere;
  - a lone tab in the middle of a line after a word: weak (tabs are used as separators there).
Plus the end-of-document token, and the "__" of dunder names (__init__, __name__).
Newlines, words and punctuation are silent.

Prediction: a fixed strength per case (values are the typical activations):
  line-start lone space 2.9, line-start run of spaces 1.7, line-start tab(s) 2.0,
  mixed tab+space run 2.6, lone tab after a space 1.4, lone tab after a word 0.4,
  lone space after spaces 0.5, run of spaces after spaces 0.2,
  end-of-document 1.3, "__" tokens 1.0, everything else 0.
"""

READS = ()


def is_blank(tok):
    """Spaces and/or tabs only, with no line break."""
    return tok != "" and tok.strip() == "" and "\n" not in tok and "\r" not in tok


def has_break(tok):
    return "\n" in tok or "\r" in tok


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else "\n"
    if tok == "<|endoftext|>":
        value = 1.3
    elif "__" in tok and tok.replace("__", "").replace(" ", "").replace("/", "").replace(".", "") == "":
        value = 1.0
    elif not is_blank(tok):
        value = 0.0
    elif "\t" in tok and " " in tok:
        value = 2.6
    elif has_break(prev):
        value = 2.9 if tok == " " else (2.0 if "\t" in tok else 1.7)
    elif "\t" in tok:
        value = 1.4 if is_blank(prev) else 0.4
    elif is_blank(prev):
        value = 0.5 if tok == " " else 0.2
    else:
        value = 0.0
    return carry, value

