    token = prefix.token_strings[-1]
    previous = ""
    if prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]
    at_line_start = previous.endswith("\n")

    if token == "<|endoftext|>":
        return None, 1.30

    if not token or not token.isspace() or "\n" in token or "\r" in token:
        return None, 0.0

    if "\t" in token:
        if " " in token and token.startswith("\t"):
            return None, 2.30
        return None, 2.10 if at_line_start else 0.70

    if set(token) == {" "}:
        if at_line_start:
            if len(token) == 1:
                return None, 2.80
            if len(token) == 2:
                return None, 2.10
            return None, 1.50
        if len(token) == 1 and previous.endswith(" "):
            return None, 0.55
        return None, 0.25 if len(token) == 2 else 0.0

    if set(token) == {"\u00a0"}:
        return None, 0.18 if len(token) == 1 else 0.70

    return None, 0.0

