"""A lexical mixture: order/count words and identifier punctuation.

Before/after and number/list/date words fire positively. Capitalization
and phrases such as natural number, named after, and linked list change
the strength. In punctuation-only tokens, one or two trailing underscores
fire strongly; longer runs do not. At-sign punctuation also fires. An
underscore after NAME is stronger, and after a one-character alphabetic
token is weaker. Other tokens return zero. Previous-token context resets at each
new document; no full-prefix text scan or token-ID lookup is needed.
"""

READS = ()

WORD_LEVELS = {
    'before': 0.89, 'after': 0.54,
    'number': 0.80, 'numbers': 0.59, 'umber': 0.34,
    'list': 0.60, 'lists': 0.43,
    'date': 0.65, 'dates': 0.65, '日期': 0.53,
}
NUMBER_KINDS = {'real', 'rational', 'complex', 'whole', 'binary'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.lstrip()
    name = text.lstrip('_.([{/<-$@\"\'')
    word = name.lower()
    previous = ''
    if (len(prefix.token_strings) > 1 and
            prefix.document_ids[-2] == prefix.document_ids[-1]):
        previous = prefix.token_strings[-2].strip()
    prior = previous.lower()
    value = WORD_LEVELS.get(word, 0.0)
    if value:
        if word in {'number', 'list', 'date', 'dates'} and name.istitle():
            value += 0.15 if word.startswith('date') else 0.08
        if word in {'number', 'numbers'}:
            if prior in {'natural', 'prime'}:
                value -= 0.40
            elif prior in NUMBER_KINDS:
                value -= 0.17
            elif prior in {'phone', 'telephone'}:
                value -= 0.32
            elif prior in {'a', 'the'}:
                value += 0.05
            if text.startswith('_'):
                value -= 0.20
        elif word == 'before' and prior in {'as', 'never'}:
            value -= 0.17
        elif word == 'after' and prior == 'named':
            value -= 0.27
        elif word == 'list' and prior == 'linked':
            value -= 0.24
        return None, value

    if '_' in text and not any(c.isalnum() for c in text):
        count = len(text) - len(text.rstrip('_'))
        if count in {1, 2}:
            value = 0.78 if count == 1 else 1.54
            value -= 0.08 * (token != text)
            if any(c in text for c in '\\})\"\'`'):
                value -= 0.22 if count == 1 else 0.50
            elif count == 2:
                value += 0.35 * ('/' in text) - 0.21 * ('.' in text)
            if text == '_' and previous == 'NAME':
                value += 0.12
            elif text == '_' and len(prior) == 1 and prior.isalpha():
                value -= 0.12
        elif count == 0:
            value = 0.07 if '{' in text else 0.23
    elif '@' in text and not any(c.isalnum() for c in text):
        value = 0.67 if text == '@' else 0.45
        if not text.endswith('@'):
            value = 0.10
        elif '[' in text or text.count('@') > 1:
            value = 0.24
        elif '/' in text:
            value = 0.78
    return None, value

