def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    boundary = token[:1].isspace()
    if word in UL_EQUIVALENTS:
        return None, UL_EQUIVALENTS[word]
    if 'ul' not in word:
        return None, 0.0
    before, after = word.split('ul', 1)
    if word in WHOLE_WORDS or 'ould' in word or 'null' in word:
        return None, 0.0
    if word.endswith('ful') and len(before) > 1:
        return None, 2.2 if len(word) == 4 and not boundary else 0.16
    if not after and len(before) <= 1:
        value = 5.5 if not before else 4.8
        if before in ('f', 'k', 's', 'v', 'o', 'd'):
            value = 3.0
        if before in ('a', 't'):
            value = 4.0
        if before == 'j':
            value = 1.4
        if boundary and not before:
            value *= 0.73
        if token.strip().startswith('Ul'):
            value *= 0.55
        return None, value
    if boundary or len(before) > 1:
        value = 0.1
        if not after and len(before) == 2:
            value = 0.4 if before.startswith('s') else 1.5
        if (boundary and len(word) <= 5 and before not in ('f', 'n', 'r')
                and after in ('l', 'k', 'le', 'se')):
            value = 1.15
        if word.startswith('ultr'):
            value = 1.3
        if word in ('bullet', 'bullets'):
            value = 2.0
        return None, value
    first = after[0]
    value = 3.1 if first in 'asku' else 2.2 if first in 'idop' else 1.65
    if first == 't':
        value = 0.7 if len(after) == 1 else 0.0
    value *= 0.75 ** (len(after) - 1) * math.exp(-0.35 * len(before))
    if after.startswith(('ate', 'ator')):
        value *= 0.5
    return None, value

