programs.luna:
"""Recognize explicit calculation and problem-solving language.

The component is especially active on words that announce mathematical
operations; it also responds to short reasoning transitions in that context.
"""
READS = ()

OPERATIONS = {
    "compute", "calculate", "determine", "find", "write", "convert",
    "divide", "multiply", "evaluate", "test", "testing", "check",
    "verify", "factor", "sort", "express", "solve", "derive",
    "simplify", "substitute", "estimate", "prove", "show",
}
MATH_CUES = {
    "equation", "equations", "number", "numbers", "integer", "integers",
    "fraction", "fractions", "sum", "product", "root", "roots", "base",
    "angle", "triangle", "formula", "variable", "solve", "equals",
    "divisible", "remainder", "polynomial", "matrix", "calculate",
}
TRANSITIONS = {"then", "so", "hence", "thus", "therefore", "if", "unless"}


def word(token):
    return token.strip().lower().strip(" \t\r\n.,:;!?()[]{}\"'`*_~")


def step(carry, prefix, upstream):
    current_doc = prefix.document_ids[-1]
    if carry is None or carry[0] != current_doc:
        recent_math = 0
    else:
        _, recent_math = carry

    token = prefix.token_strings[-1]
    w = word(token)
    recent_math = max(0, recent_math - 1)
    if w in MATH_CUES or any(ch.isdigit() for ch in token) or any(
        ch in token for ch in "=+-×÷√^"
    ):
        recent_math = 12

    operation = w in OPERATIONS
    if w.endswith("s"):
        operation = operation or w[:-1] in OPERATIONS
    if w.endswith("d"):
        operation = operation or w[:-1] in OPERATIONS
    if w.endswith("ing"):
        root = w[:-3]
        operation = operation or root in OPERATIONS or root + "e" in OPERATIONS

    if operation:
        value = 0.8
    elif w in TRANSITIONS and recent_math:
        value = 0.32
    elif w in {"times", "divisible"}:
        value = 0.45
    else:
        value = 0.0

    return (current_doc, recent_math), float(value * 0.35)

