"""Layer-0 MLP down_proj component 5286: a wh-word / relative-pronoun detector.

It is silent almost everywhere and fires on the token that opens a question or a
relative clause. Its size depends on which word it is:
  - "who" (and "whoever") is by far the strongest, about 7;
  - the who-words of other forms and languages (whose, whom, qui, quien, кто, 谁) are about 3-4;
  - the other wh-words (when, where, which, what, why, how, whether, que, ...) are about 1;
  - "that", mostly as a relative pronoun, is weak, about 0.3.
Everything else predicts 0. The component carries no state across tokens.
"""

READS = ()

WHO = {"who", "whoever"}
WHO_OTHER = {"whose", "whom", "qui", "quien", "quem", "кто", "谁", "誰"}
WH = {
    "when", "where", "which", "what", "why", "how", "whether", "whatever", "whenever",
    "wherever", "wh", "que", "quando", "cuando", "где", "которые", "которая", "который",
    "что", "où", "lorsque", "pourquoi",
}
THAT = {"that"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in WHO:
        value = 7.0
    elif word in WHO_OTHER:
        value = 3.5
    elif word in WH:
        value = 1.0
    elif word in THAT:
        value = 0.3
    else:
        value = 0.0
    return carry, value

