        value = 0.7
    elif token in ('懂', '懂得'):
        value = 1.6

    # Distinguish asking to be informed from knowing something oneself.
    if word == 'know':
        if previous in RECIPIENTS - {'you'}:
            value = 4.15
        elif previous in MODALS:
            value = 6.95
        elif previous in {'i', 'not', "'t", '’t'}:
            value = 6.45
    elif word == 'known':
        if previous in {'well', 'best', 'better'}:
            value = 3.1
        elif previous in {'is', 'was', 'be'}:
            value = 4.55
    elif word == 'about':
        if previous in {'know', 'learn', 'learned', 'learning', 'heard'}:
            value = 1.0
        elif previous in TALKING:
            value = 0.18
        elif previous in {'is', 'are', 'was', 'were'}:
            value = 0.32
    elif word in RECIPIENTS:
        if previous in {'tell', 'told', 'telling'}:
            value = 0.85
        elif previous in {'give', 'gave', 'gives'}:
            value = 0.75
        elif previous in {'show', 'showed', 'shows'}:
            value = 0.55
    elif word in {'is', 'are', 'was', 'were', "'s", '’s'}:
        if previous == 'what':
            value = 0.68 if word == 'is' else 0.54

    # Common grammatical complements of knowing, not a generic decay.
    if previous in {'know', 'knew', 'knows', 'knowing'}:
        value = KNOW_COMPLEMENTS.get(word, value)
    elif previous in {'known', '-known', 'unknown'}:
        value = KNOWN_COMPLEMENTS.get(word, value)
    elif word == 'of' and previous in {
        'knowledge', 'aware', 'awareness', 'understanding', 'conscious',
    }:
        value = 1.65
    elif word == 'more' and previous in {'learn', 'learned', 'learning'}:
        value = 0.59
    elif previous == 'зна':
        # Endings completing Russian forms of 'know'.
        value = RUSSIAN_KNOW_ENDINGS.get(word, value)
    return (doc, word), float(value)

programs.luna:
"""Score knowing, learning, communication, and explicit references to now."""

READS = ()

KNOWING = (
    "know", "learn", "discover", "believe", "sure", "clear",
    "forg", "remember", "understand", "realiz", "admit",
    "appreciat", "notice", "certain", "aware",
)
COMMUNICATION = (
    "say", "tell", "told", "ask", "inform", "report", "explain",
    "answer", "note", "mention", "describe", "read", "write", "about",
)


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if "now" in word or "know" in word:
        return None, 0.85
    if any(root in word for root in KNOWING):
