"""A small lexical sketch of formal rules and organized systems.

The component is often positive on words such as "order", "code", "law",
"structure", and "cycle". This program marks those familiar vocabulary items,
with stronger cues for capitalized legal titles. It also marks "of" just after
"order", as in names of formal orders. It does not calculate hidden states.
"""

READS = ()

LAW_WORDS = {"law", "laws", "license", "licenses", "principles"}

SYSTEM_WORDS = {
    "structure", "structures", "system", "systems", "network", "networks",
    "cycle", "cycles", "balance", "equilibrium", "framework",
}

EDGE_PUNCTUATION = " \t\r\n.,;:!?()[]{}<>\"'`“”‘’"


def step(carry, prefix, upstream):
    """Return a small positive cue for rules, systems, and ordered arrangements."""
    document = prefix.document_ids[-1]
    previous = ""
    if carry is not None and carry[0] == document:
        previous = carry[1]

    token = prefix.token_strings[-1]
    has_space = token[:1].isspace()
    raw = token.strip(EDGE_PUNCTUATION)
    word = raw.casefold()

    value = 0.0
    if word in {"order", "orders"}:
        value = 0.15 if has_space else 0.05
        if raw in {"Order", "Orders"}:
            value = 0.45 if has_space else 0.17
    elif word == "code":
        value = 0.05 if has_space else 0.0
        if raw == "Code":
            value = 0.35 if has_space else 0.02
    elif word in LAW_WORDS:
        value = 0.12 if word == "principles" else 0.10
    elif word in SYSTEM_WORDS:
        value = 0.15 if word in {"cycle", "cycles", "balance"} else 0.08
    elif word == "web":
        value = 0.18
    elif word == "very":
        value = 0.09

    if word == "of" and previous in {"order", "orders"}:
        value = max(value, 0.30)

    return (document, word), float(value)

programs.sol:
"""Approximate a short-range English collocation response.

Positive examples are 'over time', 'take on', and 'grow up'; negative ones
are 'as a result', 'take into account', 'take a look', and 'carry out'.
The program groups verb inflections, uses a few duration and article rules,
and recognizes compound endings such as add-on and full-time.  Coefficients
are rounded estimates from training examples.  Most other tokens predict
zero, with small baselines for time and particles.  Only three previous
tokens are kept, and history resets at document boundaries.
"""
READS = ()
VERBS = {
    'take': 'take takes took taking taken',
    'go': 'go goes went going gone',
    'carry': 'carry carries carried carrying',
    'hold': 'hold holds held holding',
    'move': 'move moves moved moving',
    'keep': 'keep keeps kept keeping',
    'grow': 'grow grows grew grown growing',
    'make': 'make makes made making',
    'add': 'add adds added adding',
    'build': 'build builds built building',
    'bring': 'bring brings brought bringing',
}
BASE = {form: root for root, forms in VERBS.items() for form in forms.split()}
TAKE_ENDINGS = {
    'on': 2.32, 'up': 1.28, 'over': 1.64, 'out': -1.0,
    'part': -1.48, 'place': -0.86, 'advantage': -1.30,
    'action': -0.59, 'effect': -0.85, 'charge': 1.20,
    'responsibility': 0.60, 'control': 0.42, 'precedence': 0.55,
    'for': 1.40, 'to': 0.60, 'as': 0.44, 'care': 0.28,
}


def phrase(word, previous, earlier, oldest):
    root = BASE.get(previous, previous)
    recent_take = any(BASE.get(w) == 'take' for w in (previous, earlier, oldest))
    if word == 'time':
        if previous == 'over':
            return 2.2
        if recent_take:
            if 'taken' in (previous, earlier, oldest):
                return 1.55
            return 2.55 if previous == 'some' or root == 'take' else 2.15
        if (earlier, previous) == ('for', 'a') or previous == 'extra':
            return 1.5
        if previous in {'a', 'some', 'long', 'longer', 'little', 'full'}:
            return 1.1
        if previous in {'more', 'less', 'have'}:
            return 0.65
        if previous in {'any', 'with', 'limited', 'spare', 'short'}:
            return 0.45
        if previous in {'the', 'of', 'every', 'at', 'last', 'next'}:
            return 0.28
        return 0.12
    if root == 'take' and word in TAKE_ENDINGS:
        value = TAKE_ENDINGS[word]
        if previous == 'taken':
            return {'on': 1.4, 'up': 0.88, 'over': 1.05,
                    'out': -0.75}.get(word, 0.6 * value)
        if previous == 'taking':
            return {'on': 2.05, 'up': 1.05, 'over': 1.44}.get(word, value)
        return value
    if word == 'on':
        if root in {'go', 'hold', 'move', 'carry', 'keep', 'continue', 'continued'}:
            return 0.98
        if previous in {'pass', 'passes', 'passed', 'passing', 'more'}:
            return 0.78
        if root in {'put', 'stay', 'run', 'runs', 'running', 'build', 'elaborated'}:
            return 0.53
        return 1.15 if previous in {'over', 'full'} else 0.035
    if word == 'up':
        if root in {'make', 'add'}:
            return 0.74
        if root in {'grow', 'keep', 'hold'}:
            return 0.53
        if root == 'build':
            return 0.44
        return 0.28 if root in {'go', 'bring'} else 0.075
    if word == 'over':
        return 0.52 if root == 'go' else 0.045
    if word == 'out':
        if root == 'carry':
            return -1.0
        return -0.38 if root in {'go', 'keep'} else -0.035
    if word in {'account', 'consideration'}:
        if previous == 'into':
            value = -1.34 if earlier == 'taken' else -1.75
            if BASE.get(earlier) != 'take':
                value = -0.8
            return value + (0.2 if word == 'consideration' else 0.0)
        return -0.12
    if word == 'result':
        return (-1.55 if earlier == 'as' else -0.6) if previous == 'a' else -0.06
    if previous == 'a':
        if word == 'look':
            return -1.24 if BASE.get(earlier) == 'take' else -0.96
        if word == 'while':
            return 1.45 if BASE.get(earlier) == 'take' else 0.85
        if word == 'whole':
            return -0.6 if earlier == 'as' else -0.36
        return {'few': -0.33, 'single': -0.22, 'part': -0.43,
                'consequence': -0.64, 'more': 0.49}.get(word, 0.0)
    if word == 'of' and previous == 'advantage':
        return -0.52 if BASE.get(earlier) == 'take' else 0.0
    if word == 'of' and previous == 'result':
        return -0.25 if earlier == 'a' else (0.1 if earlier == 'the' else 0.0)
    if word in {'for', 'to'} and previous == 'time' and recent_take:
        return 0.75
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        oldest = earlier = previous = ''
    else:
        _, oldest, earlier, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    root = BASE.get(previous, previous)
    # Leading space marks a new word; no space can mark a compound ending.
    if token[:1].isspace():
        value = phrase(word, previous, earlier, oldest)
    elif previous == 'over' and word.isalpha():
        value = 0.65
    elif previous == 'full' and word == '-on':
        value = 1.35
    elif root == 'add' and word in {'-on', '-ons', 'ons'}:
        value = 1.75 if word == '-on' else 0.85
    elif root in {'take', 'make'} and word == '-up':
        value = 0.95 if root == 'take' else 0.59
    elif previous == 'full' and word in {'-time', 'time'}:
        value = 0.71
    else:
        value = 0.0
    if word == 'time' and token.strip().isupper():
        value *= 0.65
    return (doc, earlier, previous, word), float(value)

programs.haiku:
"""Phrase-level rules for layers.0.mlp.down_proj:5295 (layer 0, MLP down projection).

What it does: this one rank-one piece of the layer-0 MLP writes a signed "phrase sense"
signal into the residual stream. It is silent on almost every token, and fires on the
second word(s) of a few fixed English phrases, found by reading the top activations:

  positive (about +1 to +2.5)
    - the noun "time" used as a duration: "take time", "takes some time", "over time",
      "for a while", "at a time", "for a long time"  (strongest after take/takes/took)
    - the particle after a "take" verb or a movement verb: "take on", "take over",
      "take up", "went on", "hold on", "carry on", "make up"

  negative (about -1 to -1.5)
    - "As a result", "into account", "into consideration", "carried out",
      "take part", "take place", "take advantage", "take a look"
  weakly negative (about -0.3)
    - "a few", "a whole", "a single", "a part", "a small", "a very", "as well", "the same"

Everything else is predicted as 0 (a bare "time" gets a small +0.2). The program reads only
the two words before the current one, within the same document.
"""

READS = ()

TAKE = {"take", "takes", "took", "taken", "taking", "will take"}
MOVE = {"go", "goes", "went", "going", "hold", "held", "carry", "carried", "move", "moves",
        "moving", "make", "made", "add", "added", "grew", "grow", "put", "keep", "kept"}
QUANTITY = {"few", "whole", "single", "part", "consequence", "small", "very"}


def value(p2, p1, cur):
    """p2, p1: the two words before `cur` (lower case, '' if none); cur: this word."""
    if cur == "time":
        if p1 in ("over", "for", "upon"):
            return 2.0 if p1 == "over" else 1.4
        if p2 in TAKE or p1 in TAKE:
            return 2.4
        if p1 in ("a", "some", "long", "short"):
            return 1.0
        return 0.2
    if cur in ("on", "over", "up"):
        if p1 in TAKE:
            return 2.0
        if p1 in MOVE:
            return 1.0
        return 0.0
    if cur == "more" and p1 == "a":
        return 0.5
    if cur == "while" and p1 == "a":
        return 0.9
    if cur == "result" and p1 == "a":
        return -1.5
    if cur in ("account", "consideration") and p1 == "into":
        return -1.4
    if cur == "out" and p1 in ("carry", "carried", "carrying"):
        return -1.0
    if cur in ("place", "part", "advantage") and p1 in TAKE:
        return -1.3
    if cur == "look" and p1 == "a":
        return -1.0
    if cur in QUANTITY and p1 == "a":
        return -0.3
    if cur == "well" and p1 == "as":
        return -0.2
    if cur == "same" and p1 == "the":
        return -0.1
    return 0.0


def step(carry, prefix, upstream):
    toks = [t.strip().lower() for t in prefix.token_strings]
    docs = prefix.document_ids
    cur = toks[-1]
    p1 = toks[-2] if len(toks) > 1 and docs[-2] == docs[-1] else ""
    p2 = toks[-3] if len(toks) > 2 and docs[-3] == docs[-1] else ""
    return carry, float(value(p2, p1, cur))

programs.luna:
"""Approximate a few recurring lexical cues in this component's activation.

Give positive estimates to on/up/over and a few time words. Give negative
estimates to several formulaic result phrases. All estimates are scaled by
0.45; other tokens receive zero. This is a small surface-text shortcut.
"""
READS = ()

CONTINUATION = {"on": 0.25, "up": 0.25, "over": 0.25}
TIME_WORDS = {"time": 0.25, "year": 0.22, "years": 0.22, "while": 0.30}


def clean(text):
    return text.strip().casefold().strip(".,:;!?()[]{}\"'“”")


def step(carry, prefix, upstream):
    t = prefix.position
    word = clean(prefix.token_strings[-1])
    value = CONTINUATION.get(word, TIME_WORDS.get(word, 0.0))
    same_doc = t > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]
    if same_doc:
        previous = clean(prefix.token_strings[-2])
        two_back = ""
        if t > 1 and prefix.document_ids[-1] == prefix.document_ids[-3]:
            two_back = clean(prefix.token_strings[-3])

        as_a_phrase = previous == "a" and two_back == "as"
        as_an_example = previous == "an" and two_back == "as"
        if word in {"result", "whole", "consequence"} and as_a_phrase:
            value = -0.8
        elif word == "example" and as_an_example:
            value = -0.65
        elif word == "account" and previous == "into":
            value = -0.7
        elif word == "out" and previous in {"carry", "carried"}:
            value = -0.7
        elif word == "look" and previous == "a" and two_back == "take":
            value = -0.8

    return None, float(value * 0.45)

programs.sol:
"""A local decimal-transition signal, strongest after zero.

The current digit matters: after 0, 1 and 2 are strongly positive,
while 7--9 are negative. After 9 the response rises with the digit.
Repeated zeros strengthen the first profile. A weaker version survives
one intervening number separator, or follows 5. High digits also give a
small positive signal after 7 or 8. Other text is near zero,
with a small negative response just after a zero. ASCII and fullwidth
digits share these rules; the two-token memory resets at document boundaries.
"""

READS = ()
# Calibrated responses for the ten possible current decimal digits.
AFTER_ZERO = (1.65, 3.84, 2.57, 1.37, 0.86, 0.09, -0.19, -0.78, -1.08, -1.83)

SEPARATORS = {'.': 0.34, ',': 0.18, '-': 0.14, '/': 0.10, ':': 0.06}


def digit(token):
    if len(token) == 1:
        if '0' <= token <= '9':
            return ord(token) - ord('0')
        if '０' <= token <= '９':
            return ord(token) - ord('０')
    return -1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before = '', ''
    else:
        _, previous, before = carry
    d, p, pp = digit(token), digit(previous), digit(before)
    value = 0.0
    if d >= 0:
        if p == 0:
            value = AFTER_ZERO[d] * (1.15 if pp == 0 else 1.0)
        elif p == 9:
            value = 0.247 * d - 0.29
        elif p == 5:
            value = 0.14 * AFTER_ZERO[d]
        elif p in (7, 8):
            value = 0.10 * max(0, d - 5)
        elif pp == 0:
            scale = 0.0
            if previous in SEPARATORS:
                scale = SEPARATORS[previous]
            elif previous.isspace():
                scale = 0.10 if '\n' in previous else 0.28
            # An intervening separator especially weakens the 0-to-0 case.
            value = scale * (0.9 if d == 0 else AFTER_ZERO[d])
    elif p == 0:
        value = -0.06 if token.strip() == '.' else -0.17
    return (doc, token, previous), float(value)

programs.luna:
"""Estimate activations for digits continuing a number.

The strongest repeatable responses occur after two zeros (especially 200x),
after 20, and in the 19xx range. A plain zero-to-three pattern also catches
common continuations when the preceding text ends in zero. Other tokens get 0.
"""
READS = ()

AFTER_ZERO = {"0": 1.7, "1": 3.8, "2": 2.5, "3": 1.3}
AFTER_20 = {
    "0": 1.7, "1": 4.0, "2": 2.7, "3": 1.4,
    "7": -0.8, "8": -1.1,
}
AFTER_19 = {
    "0": -0.2, "2": 0.25, "3": 0.47, "4": 0.72,
    "5": 0.9, "6": 1.2, "7": 1.45, "8": 1.8, "9": 2.0,
}
AFTER_200 = {
    "0": 2.0, "1": 4.5, "2": 3.3, "3": 1.5,
    "5": 0.15, "6": -0.2, "7": -1.0, "8": -1.3, "9": -2.2,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    tail = "" if carry is None or carry[0] != doc else carry[1]

    value = 0.0
    if len(token) == 1 and token in "0123456789":
        if tail.endswith("200"):
            value = AFTER_200.get(token, 0.0)
        elif tail.endswith("19"):
            value = AFTER_19.get(token, 0.0)
        elif tail.endswith("20"):
            value = AFTER_20.get(token, 0.0)
        elif tail.endswith("0"):
            value = AFTER_ZERO.get(token, 0.0)

    return (doc, (tail + token)[-5:]), float(value)

