programs.haiku:
"""Locative and setting words, as a reader would name them. A Chinese word ending
in a place or relation character gets a negative activation: strongest for 上 (on),
中 (in), 内 (within), 里 (inside); weaker for 外 (outside), 前 (before), 下 (under),
边 (side), 后 (after). Examples: 床上, 路上, 生活中, 过程中, 情况下, 范围内, 门外, 婚后.
Single locative characters are weaker, and English setting words (indoor, outdoor)
are negative too. Common non-locative uses (以上, 以下, 以内, 之中, 一下, 中文, 台中)
are left at zero."""

READS = ()

ENDING = {"上": -3.0, "中": -3.0, "内": -2.8, "里": -1.8, "外": -1.1, "前": -1.0,
          "下": -1.0, "边": -1.0, "后": -0.9}
SINGLE = {"上": -0.7, "内": -0.4, "里": -0.4, "下": -0.3}
TIME_FRAME = {"目前": -1.2, "当前": -0.5, "晚上": -1.6, "早上": -1.0, "国内": -1.9,
              "其中": -0.7, "实际上": -1.7, "事实上": -2.9, "基本上": -1.3, "现场": -0.7}
SETTING_EN = {"indoor", "outdoor", "outdoors", "underwater", "roadside", "statewide", "abroad",
              "onstage", "airborne"}
NOT_LOC = {"以上", "以下", "以内", "之上", "之下", "之中", "一下", "上下", "高中", "中文", "中的",
           "台中", "其中", "当中", "这里", "那里", "哪里"}


def is_cjk(ch):
    return "一" <= ch <= "鿿"


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1].strip()
    if s in TIME_FRAME:
        v = TIME_FRAME[s]
    elif s in SETTING_EN:
        v = -1.1
    elif len(s) == 1:
        v = SINGLE.get(s, 0.0)
    elif len(s) >= 2 and all(is_cjk(c) for c in s) and s[-1] in ENDING and s not in NOT_LOC:
        v = ENDING[s[-1]]
    else:
        v = 0.0
    return None, float(v)

