programs.haiku:
"""Sentence-end punctuation, signed by the word before it (layers.0.mlp.down_proj:5300).

The component is a sentence-end detector. It is near zero on almost every token and
responds only to sentence-final punctuation: a period, an ellipsis, or an exclamation
mark. What it writes depends on the word before the mark:
- a period after a digit ("3.", "1.5" , "v2.0"): strongly negative (about -0.6);
- a period after an ordinary lowercase word of 4+ letters, the end of a prose sentence:
  mildly positive (about +0.19 when the word has 4+ letters, +0.05 for 3 letters);
- an ellipsis or "!" after an ordinary lowercase word: positive (about +0.5, "..." +1.2);
- after a capital letter, a single letter or a short token (initials, "Fig.", "Mr.")
  the period is about zero, and so is every other token.
"""
READS = ()

SENTENCE_END = {".", "...", "!", "..", "....", "…"}


def word_strength(prev):
    """How strongly a word before a period signals end-of-sentence prose."""
    if prev.isdigit():
        return -0.6
    if not prev.isalpha() or not prev.islower():
        return -0.03
    return 0.05 if len(prev) < 4 else 0.19


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    if tok not in SENTENCE_END:
        return carry, 0.0
    strength = word_strength(prev)
    if tok == ".":
        return carry, strength
    if strength < 0:
        return carry, 0.0
    return carry, 1.2 if tok == "..." else 0.5

