"""A punctuation cue: periods after numbers dip; sentence stops rise."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].rstrip()
    if not token or token[-1] not in ".!?":
        return None, 0.0

    doc = prefix.document_ids[-1]
    previous = ""
    for i in range(len(prefix.token_strings) - 2, -1, -1):
        if prefix.document_ids[i] != doc:
            break
        previous = prefix.token_strings[i]
        if previous.strip():
            break

    last = previous.rstrip()[-1:] if previous.strip() else ""
    if not last.isalnum():
        return None, 0.0
    numeric_period = token.endswith(".") and token != "..." and last.isdigit()
    return None, -0.21 if numeric_period else 0.13

