"""A lexical publication cue, including nearby metadata and word endings.

Forms of 'publish' give the largest response. Periodicals, media, publishing
roles, and organizing/hosting events give weaker responses. These groups also
include some Chinese/Japanese equivalents. A following preposition or bound
word ending inherits a fraction of the cue. 'Published on/by/in' headings
receive special treatment. Weak activity outside this vocabulary is ignored.
"""

READS = ()

# Values approximate strengths, not probabilities. Plurals share a group.
VOCABULARY = (
    (6.0, {'刊', '期刊'}),                         # periodical/publication
    (4.8, {'出版'}),                              # publish
    (3.0, {'出版社', '刊登', '杂志', '雜誌'}),      # publisher/magazine
    (2.1, {'举办', '舉辦', '主办', '主辦', '创办', '創辦',
           '召开', '召開', '办', '辦', '发表', '發表', 'изд'}),
    (1.5, {'magazine', 'newsletter', 'isbn', '印刷'}),
    (1.35, {'conference', 'editorial', '责任编辑'}),
    (1.0, {'newspaper', 'broadcast', 'broadcasting', 'podcast', 'subscriber',
           'paperback', 'prestigious', 'advertised', 'doi', 'issn', 'pubmed',
           '发行', '發行', '发布', '發布', '订', '訂', '订阅', '訂閱',
           '报', '報', '版', '成立', '上映', '投稿', '举行', '舉行'}),
    (0.8, {'launch', 'launched', 'launching', 'establishment', 'advertising',
           'advert', 'hosted', 'venue', 'aired', 'printing', 'publicity',
           'postage', 'journalism', 'premiered', 'proceedings'}),
    (0.65, {'establish', 'established', 'edition', 'manuscript', 'premiere',
            'scheduled', 'scheduling', 'subscribe', 'subscription', 'supplier',
            'manufacturer', 'partner'}),
    (0.45, {'press', 'printed', 'printer', 'issued', 'journalist', 'host',
            'hosting', 'announced', 'producer', 'funded', 'funding', 'offices',
            'advertisement', 'citation', 'establishing', '社', '印', '推出',
            '编辑', '編輯'}),
)


def lexical(token):
    raw = token.strip()
    word = raw.lower()
    # Publishing APIs and hyphenated words are cues too, unlike 'public'.
    core = word.lstrip('.-_/')
    if core.startswith('publish'):
        word = core
    if word in {'publisher', 'publishers', 'ublisher'}:
        return 5.7 if word.endswith('s') else 6.0
    if word in {'published', 'ublished'}:
        if raw == 'Published':
            return 5.5 if token[:1].isspace() else 6.4
        return 3.6 if token == 'published' else 4.7
    if word == 'publishing':
        return 5.1
    if word in {'publish', 'publishes', 'ublish'}:
        return 4.2
    if word in {'publication', 'publications'}:
        return 2.5 if word.endswith('s') else 3.1
    if word == 'unpublished':
        return 1.4
    if word in {'publié', 'publicado', 'publicada'}:
        return 1.9
    if word in {'pub', 'publ', 'ubl'}:
        return 2.6 if word == 'ubl' else 1.2
    if word in {'journal', 'journals', 'ournal', 'журнал', 'жур'}:
        return 1.8 if raw[:1].isupper() or word == 'жур' else 2.4
    if word in {'editor', 'editors'}:
        return 1.2 if token[:1].isspace() else 0.7
    for value, words in VOCABULARY:
        if word in words or (word.endswith('s') and word[:-1] in words):
            return value
    if word in {'posted', 'edited'}:
        return 0.12
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    reset = carry is None or carry[0] != doc
    previous, previous_word = (0.0, '') if reset else carry[1:]
    base = lexical(token)
    if reset and token == 'Published':
        base = 8.75
    value = base
    word = token.strip().lower()

    if previous_word == 'Published' and word in {'in', 'by', 'on', ':'}:
        if word == 'in':
            value += 3.8
        elif word == ':':
            value += 3.1
        else:
            value += 5.4 if previous > 8.0 else 4.9
    elif word in {'in', 'by', 'on', 'of'}:
        fraction = 0.55
        noun = previous_word.lower()
        if noun.startswith('publisher'):
            fraction = 0.4 if word == 'of' else 0.08
        elif noun in {'publication', 'publications'}:
            fraction = 0.7 if word == 'of' else 0.25
        value += fraction * previous
    elif word in {'ing', 'ed', 'er', 'ers', 's', 'ation', 'ations'}:
        value += 0.9 * previous
    elif word == ':':
        value += 0.25 * previous

    cue = base
    if word in {'posted', 'edited'}:
        cue = 1.2 if token.strip()[:1].isupper() else 0.8
    return (doc, cue, token.strip()), float(value)

