PUBLISH = 5.0       # publish, publisher, published, publishing, publishes
PUBLICATION = 3.0   # publication, publications
PERIODICAL = 2.0    # journal, magazine, 杂志, 期刊
MEDIA = 1.2         # conference, editor, newspaper, broadcast, pub, 发表, 报纸


def _level(token):
    s = token.strip().lower()
    if "unpublish" in s:
        return 0.0
    if "ublish" in s:
        return PUBLISH
    if "出版" in s:
        return PUBLISH
    if "publication" in s:
        return PUBLICATION
    if s in ("journal", "journals", "magazine", "magazines", "杂志", "期刊"):
        return PERIODICAL
    if s in ("conference", "conferences", "editor", "newspaper", "newspapers",
             "broadcast", "pub", "pubs", "发表", "报纸"):
        return MEDIA
    return 0.0


def step(carry, prefix, upstream):
    return None, float(_level(prefix.token_strings[-1]))

