    (-0.35, '群众 群眾 劳动合同 大众 党的 团结 统战 职工 打工 农民工 反抗 剥削'.split()),
    (-0.28, '党 黨 资产 資產 资本 勞 农场 農場'.split()),
)
CHINESE = {w: value for value, words in CHINESE_GROUPS for w in words}
MARKERS = {'<tool_call>': -0.24, '<tool_response>': -0.15,
           '<think>': -0.20, '</tool_call>': 0.06}

# Recent vocabulary that can signal class or left-wing politics.
POLITICS = re.compile(
    r'\b(?:communis\w*|socialis\w*|marx\w*|soviet|proletar\w*|'
    r'bourgeois|labor|labour|union|unions|wages|peasant\w*)\b')
WORD_END = re.compile(r'[a-z]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    text = token.strip()
    word = text.lower()
    joined = old + token.lower()
    value = -0.001
    chinese = None
    if not text.isascii():
        chinese = next((v for root, v in CHINESE.items() if root in text), None)
    if text in MARKERS:
        value = MARKERS[text]
    elif chinese is not None:
        value = chinese
    else:
        value = WORDS.get(word, value)
        # Ideological suffixes refer back to a visible word stem.
        if text.isalpha() and token == text:
            match = WORD_END.search(joined)
            full = match.group() if match else word
            if word in {'ism', 'isms', 'ist', 'ists', 'ismo', 'ista', 'isme'}:
                value = -0.12
                if full.startswith('socialis'):
                    value = -0.95
                elif full.startswith(('communis', 'capitalis', 'feminis', 'fascis')):
                    value = -0.65
                elif full.startswith('marxis'):
                    value = -0.40
                elif full.startswith('anarchis'):
                    value = -0.20
            elif full == 'emancipation' and word != full:
                value = -0.65
            elif re.search(r'\b(labor|labour)$', old):
                value = {'ers': -0.36, 'er': -0.22, 'ing': -0.14}.get(word, value)
            elif full == 'strikers' and word != full:
                value = -0.38
        # Comparable vocabulary in German, Russian and Korean.
        if word.startswith('труд'):
            value = -0.49
        elif word == 'arbeit':
            value = -0.40
        elif word == '노':
            value = -0.35

        political = bool(POLITICS.search(old[-80:]))
        if text in {'Labor', 'Labour'}:
            value = -0.94 if token.startswith(' ') else -0.62
            if re.search(r'\b(national|international|australian)\s*$', old):
                value = -1.35
        if word in {'party', 'parties'}:
            value = -0.40 if text[:1].isupper() and token.startswith(' ') else -0.13
            if political:
                value = -1.35 if text[:1].isupper() else -0.75
            elif re.search(r'\b(dinner|birthday|third|loan)\s*$', old):
                value = -0.01
        if word in {'union', 'unions'}:
            value = -0.18 if text[:1].isupper() else -0.23
            if re.search(r'\b(soviet|labor|labour|trade|working|democratic)\s*$', old):
                value = -0.65
            elif re.search(r'\b(european|credit)\s*$', old):
                value = -0.02
        if word in {'class', 'classes', '-class'}:
            value = -0.06 if token.startswith(' ') else 0.01
            if re.search(r'\b(working|peasant|ruling|bourgeois)\s*$', old):
                value = -0.85
            elif re.search(r'\bmiddle\s*$', old):
                value = -0.55
            elif re.search(r'\b(public|private|export|abstract|static|data)\s*$', old):
                value = 0.02
        if word in {'conditions', '-intensive'}:
            value = -0.02
            if re.search(r'\b(working|labor|labour)\s*$', old):
                value = -0.60
        if word in {'farm', 'farms'} and re.search(r'\bcollective\s*$', old):
            value = -0.80
        if word == 'left' and political:
            value = -0.65
        if text in {'Worker', 'Workers'}:
            value = -0.43
        if word in {'workers', 'worker', 'movement', 'movements'} and political:
            value = -0.55
        # A small local boost for nearby ideological vocabulary.
        elif word in WORDS and WORDS[word] < -0.5 and political:
            value *= 1.15
    return (doc, joined[-100:]), float(value)

"""A local 'to' construction detector.

Return-to, switch-to and movement/change-to phrases get negative responses;
'going to' is included. An intervening object or spatial word can retain a
weaker response. Common non-motion 'to' constructions are weakly positive.
Other destination prepositions respond less strongly, while 'return' and
its returned expression are positive. Unclassified 'to' is weakly negative;
other tokens are zero. Keep only a short, document-local tail.
"""
import re

READS = ()


def forms(roots):
    words = set()
    for root in roots.split():
        stem = root[:-1] if root.endswith('e') else root
        plural = root + ('es' if root.endswith(('s', 'x', 'ch', 'sh')) else 's')
        past = root + ('d' if root.endswith('e') else 'ed')
        words.update((root, plural, past, stem + 'ing'))
        if root in {'refer', 'transfer', 'travel'}:
            words.update((root + root[-1] + 'ed', root + root[-1] + 'ing'))
    return words


PHRASES = [
    (-5.8, forms('return')),
    (-5.1, forms('switch revert transition')),
    (-4.0, forms('move turn convert shift jump migrate redirect')),
    (-2.4, forms('transfer change translate transform default travel proceed')),
    (-1.2, forms('refer direct route send ship introduce')),
    (-0.8, forms('lead') | {'led', 'out', 'off', 'set', 'prior', 'limited'}),
]
NON_MOTION = set(('able unable likely possible impossible necessary important '
                  'easy difficult willing ready required expected designed used '
                  'try trying enough how close equal similar compared related').split())
OBJECTS = set(('it them him her me this that file files value values term terms '
               'number numbers output string keys types power energy function '
               'program issue question data site here there directly ahead').split())
PARTICLES = set('back on over forward down up in'.split())


def response(word):
    if word == 'back':
        return -3.8
    if word == 'go':
        return -3.7
    if word in {'went', 'goes', 'gone'}:
        return -3.1
    if word in {'going', 'get', 'getting', 'welcome'}:
        return -2.3
    if word in {'come', 'comes', 'came', 'coming', 'down', 'over', 'forward'}:
        return -1.7
    if word in PARTICLES | {'way', 'order', 'addition', 'attention'}:
        return -0.4
    if word in NON_MOTION:
        return 0.3
    if word in {'need', 'needs', 'have', 'has', 'had', 'according', 'due'}:
        return 0.15
    for value, words in PHRASES:
        if word in words:
            return value
    return -0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    match = re.search(r'([A-Za-z]+)\s*$', tail)
    previous = match.group(1).lower() if match else ''
    value = 0.0
    if word in {'to', '-to', '_to', 'into', 'onto', 'toward', 'towards'}:
        value = response(previous)
        if previous in OBJECTS | PARTICLES:
            words = re.findall(r'[A-Za-z]+', tail.lower())[-4:]
            for distance, earlier in enumerate(reversed(words[:-1]), 1):
                cue = response(earlier)
                if cue < -1.7:
                    if previous == 'back':
                        value += 0.45 * cue / distance
                    elif previous == 'up':
                        value += 0.3 * cue / distance
                    else:
                        value = min(value, 0.75 * cue / distance**0.5)
                    break
        if previous == 'back' and match.group(1)[0].isupper():
            value -= 1.2  # the navigation phrase 'Back to'
        if word in {'into', 'onto', 'toward', 'towards'}:
            floor = -0.15 if word == 'into' else -0.7
            value = min(floor, 0.45 * value)
    elif word == 'return':
        value = 0.43
    elif previous == 'return':
        constants = {'true', 'false', 'null', 'nil', 'none', 'this'}
        value = 1.0 if word in constants else 0.3
    return (doc, (tail + raw)[-80:]), float(value)

programs.haiku:
"""Layer-0 MLP down-projection, component 5303: the "to" direction detector.

It is a negative response on the word "to" (and "into", "towards") that marks a
destination or direction, and it is strongest when the word before it is a verb of
going, returning, moving or changing: "return to" (about -6), "moved to", "switch to",
"going to", "back to" (-2 to -4). After verbs of reference or leading ("refer to",
"lead to", "set to", "me to") it is moderately negative (about -1). After words that
introduce an infinitive ("willing to", "enough to", "required to", "need to", "how to",
"ready to") it is mildly positive (about +0.4). Other "to" is about -0.2 (for example
"according to" is near 0).

Two more small positive responses: the word "return" (+0.4), and "true"/"false"/"None"
right after "return" (+1.1), which is the value returned from a function.

Everything else is 0. The program only looks at the current token and the one before.
"""

READS = ()

TO_WORDS = {"to", "into", "towards", "toward", "onto"}
RETURN_WORDS = {"return"}
LITERALS = {"true", "false", "True", "False", "None"}

# Verbs and adverbs of going, returning, moving or changing state.
MOTION = {
    "return", "returned", "returning", "returns", "revert", "switch", "switched", "switches",
    "move", "moved", "moving", "moves", "turn", "turned", "turning", "convert", "converted",
    "go", "going", "goes", "went", "gone", "back", "come", "coming", "came", "walk",
    "travel", "drive", "head", "heading", "proceed", "transfer", "transferred", "bring",
    "brought", "send", "sent", "changed", "change", "changes", "get", "got", "down", "out",
}
# Verbs of reference, leading and pointing.
REFERENCE = {
    "refer", "referred", "referring", "refers", "reference", "lead", "leading", "leads",
    "led", "point", "points", "set", "directed", "map", "mapped", "me", "you", "them", "it", "us",
}
# Words that introduce an infinitive: ability, willingness, necessity, purpose.
INFINITIVE = {
    "willing", "unlikely", "likely", "unable", "enough", "sufficient", "refused", "required",
    "need", "needs", "needed", "used", "ready", "how", "attempt", "attempts", "failed",
    "allowed", "prepared", "necessary", "possible", "expected", "able", "trying", "try",
    "wanted", "want", "decided", "asked", "difficult", "easy", "hard", "had", "as",
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    same_doc = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    if token in TO_WORDS:
        if prev in MOTION:
            value = -3.0
        elif prev in REFERENCE:
            value = -0.8
        elif prev in INFINITIVE:
            value = 0.3
        else:
            value = -0.2
    elif token in RETURN_WORDS:
        value = 0.4
    elif token in LITERALS and prev == "return":
        value = 1.1
    else:
        value = 0.0
    return carry, float(value)

