"""Approximate the component with clues from the current and previous words.

`to` gets a negative guess, stronger after selected verbs and verb-like endings.
Related prepositions get smaller negative guesses; `return` gets a positive one.
"""

READS = ()

VERBS_BEFORE_TO = {
    "go", "goes", "going", "went", "move", "moves", "moving",
    "moved", "return", "returns", "returning", "transport",
    "transported", "lead", "leads", "led", "send", "sent", "take",
    "taken", "come", "came", "travel", "traveling", "head", "headed",
    "point", "points", "refer", "refers", "referred", "resolve",
    "resolves", "resolved", "declined", "assigned", "owe", "owes",
}


def step(carry, prefix, upstream):
    words = prefix.token_strings
    docs = prefix.document_ids
    current = words[-1].strip().lower()
    if current == "to":
        if len(words) > 1 and docs[-2] == docs[-1]:
            previous = words[-2].strip().lower()
            if previous in VERBS_BEFORE_TO:
                return None, -0.65
            if previous.endswith(("ing", "ed")):
                return None, -0.4
            if previous in {"back", "out", "up"}:
                return None, -0.4
        return None, -0.12
    if current in {"into", "toward", "towards"}:
        return None, -0.1
    if current == "return":
        return None, 0.15
    return None, 0.0

programs.sol:
"""Detect 'before' and 'prior to', with weaker multilingual equivalents.

Capitalization and attached code punctuation affect the word's strength.
This is a sparse approximation: unrelated spelling and context responses
are left at a near-zero baseline.
"""

READS = ()

# These are ways of saying 'before', not arbitrary vocabulary items.
BEFORE_TRANSLATIONS = {
    'bevor': 0.60,       # German
    'før': 0.54,         # Danish/Norwegian
    'antes': 0.35,       # Spanish/Portuguese
    'avant': 0.19,       # French
    '之前': 0.11,         # Chinese
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    value = -0.001
    if lower.lstrip('_.-(@') == 'before':
        value = 1.45
        if token == 'Before':
            value = 1.60
        elif token.startswith('@'):
            value = 0.71
        elif token.startswith('('):
            value = 1.18
        elif word == 'Before' or token.startswith(('_', '.')):
            value = 1.37
        elif token.startswith('-'):
            value = 1.59
    elif lower == 'beforeeach':
        value = 0.68  # A before-test callback in code.
    elif lower == '.insertbefore':
        value = 0.23
    elif lower == 'fore' and previous.strip() == 'BE':
        value = 0.66  # Uppercase BEFORE split into BE + FORE.
    elif lower == 'beforehand':
        value = 0.27
    elif word == 'belum' and previous.strip().lower() == 'se':
        value = 0.83  # Indonesian sebelum, split into se + belum.
    elif lower == 'to' and previous.strip().lower() == 'prior':
        value = 0.75 if previous.strip() == 'prior' else 0.70
    elif lower == 'prior':
        value = 0.17 if word.islower() else 0.05
    elif token.startswith(' ') or lower == '之前':
        value = BEFORE_TRANSLATIONS.get(lower, value)
    return (document, token), value

