"""Mark 'before' and a few clear temporal equivalents in the current token.

The English spelling is the dominant trigger.  Norwegian 'før' and Indonesian
'belum' can also signal a time before something; 'to' counts only in the
explicit phrase 'prior to'.
"""

READS = ()

BEFORE_VALUE = 1.4
OTHER_VALUES = {"før": 0.65, "belum": 0.75}
PUNCTUATION = " \t\r\n.,;:!?()[]{}<>\"'_*"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].casefold().strip(PUNCTUATION)
    if token == "before":
        return None, BEFORE_VALUE
    if token in OTHER_VALUES:
        return None, OTHER_VALUES[token]
    if token == "to" and prefix.position > 0:
        previous = prefix.token_strings[-2].casefold().strip(PUNCTUATION)
        if previous == "prior":
            return None, 0.8
    return None, 0.0

