"""A negative lexical detector centered on Chinese 才 and 材.

才 means 'only then' or talent; its longer compounds generally respond less.
材 and material/talent words, 'before', 'again', and selected multilingual
forms have smaller responses. This approximates token spellings, not whole
sentence meanings. Unlisted text is neutral. Split Chinese characters are
recognized only when enough bytes have arrived to decode them.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    same_doc = (prefix.position > 0
                and prefix.document_ids[-2] == prefix.document_ids[-1])
    if token == '\ufffd' and same_doc:
        char = prefix.text_prefixes[-1][-1:]
        if char == '才':
            return None, -9.95
        if char == '材':
            return None, -4.5
        if char == '纔':                        # variant of 才
            return None, -5.35
    if '才' in token:
        if token == '刚才':                     # just now
            value = -0.67
        elif token in {'才', '我才', '这才'}:
            value = -9.8
        elif token == '人才':                   # talented person
            value = -7.75
        elif token in {'才是', '才会', '才有'}:
            value = -7.25
        else:
            value = -9.95 / len(token) ** 0.8
    elif token == '材':
        value = -5.45
    elif '材' in token:
        value = -1.65 if token in {'材料', '新材料'} else -0.85
    elif token in {'再', '后再', '然后再'}:
        value = -1.87
    elif token == '재':                         # Korean material/talent
        value = -2.0
    elif token in {'mới', 'cái', 'tài'}:         # Vietnamese lexical forms
        value = {'mới': -3.3, 'cái': -2.6, 'tài': -1.4}[token]
    elif token in {'れば', 'たら', 'したら', 'すれば', 'いれば',
                   'であれば', 'があれば'}:      # Japanese condition endings
        value = -1.2
    else:
        word = token.strip('._-/(:@').lower()
        if word == 'before':
            value = -1.18
        elif word in {'material', 'materials'}:
            value = -1.15 if word.endswith('s') else -0.8
        elif word in {'talent', 'talents'}:
            value = -1.8
        elif word in {'talented', 'genius', 'intellect'}:
            value = -0.7
        elif word.startswith('материал'):
            value = -1.25 if word.endswith(('ов', 'ы')) else -0.8
        else:
            value = 0.0
    return None, value

programs.haiku:
"""layers.0.mlp.down_proj:5307, a lexical detector for "talent" and "material" words.

The component is almost entirely a function of the current token. It goes strongly
negative on the Chinese character 才 ("only then / just", and in talent words such as
人才, 才能, 才是, 这才) and on the bare character 材 ("material / timber / talent").
It is weakly negative on compounds of 材 and 财 (材料, 身材, 素材, 财富), on the English
words "talent", "genius", "material(s)" and "before", on 再 ("again"), and on a few
other particles (Vietnamese mới, cái). Everything else is about zero. 刚才 ("just now")
is the exception among 才 words: it is weak.

The program reads only the current token (`prefix.token_strings[-1]`) and returns the
typical activation for its group. It has no carry state.
"""

READS = ()


def value(token: str) -> float:
    word = token.strip().lower()
    if token == "才":
        return -10.0  # the bare character 才
    if "才" in token and token != "刚才":
        return -7.0  # 才 words: 这才, 人才, 才能, 才是, 才会
    if token == "材":
        return -5.7  # the bare character 材
    if word in ("talent", "talents"):
        return -1.8
    if "材" in token or "财" in token:
        return -1.0  # 材料, 身材, 素材, 财富 ...
    if "material" in word:
        return -1.0
    if "before" in word:
        return -1.2
    if token == "再":
        return -1.9  # again
    if token in (" mới", " cái"):
        return -2.5  # Vietnamese "just" / "this"
    return 0.0


def step(carry, prefix, upstream):
    return carry, value(prefix.token_strings[-1])

