    else:
        value = 0.0
    return None, value

programs.sol:
"""Mostly a lexical detector for information: the English noun, info in code,
and cognates/translations. Informing, knowledge, news, and education words
respond less strongly. Privacy/quantity modifiers weaken the English noun;
suddenness has the opposite sign. Only the preceding token is remembered to
recognize two-token words and information-phrase continuations. Unmatched
text is zero; weak background and incidental lexical responses are omitted.
"""
READS = ()

# Familiar words and stems, grouped by approximate response strength.
MEDIUM_INFORMATION = {
    'informations', 'informationen', 'informatie', 'informação', 'informações',
    'информации', 'информацию', 'информацией', '정보',
}
OTHER_INFORMATION = {
    'информация', 'информ', 'информацион', 'المعلومات', 'علومات',
    '資訊', '情報', '情報を',
}
INFORM_COGNATES = {
    'información', 'informazioni', 'informacion', 'informasi',
    'informacji', 'informacje',
}
INFORMING = {'inform', 'informat', 'informative', 'informing'}
KNOWLEDGE = {'knowledge', 'notice', '知', '知識', '知识', '了解', '通知'}
NEWS_EDUCATION = {
    'news', 'details', 'education', 'educated', 'educate', 'educational',
    '新闻', '新聞', '教育',
}
PRIVACY = {'personal', 'sensitive', 'confidential'}
MORE = {'more', 'additional', 'enough'}


def step(carry, prefix, upstream):
    raw, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    prior = previous.strip().lower()
    spelling = raw.strip()
    word = spelling.lstrip('_.-/(').lower()
    value = 0.0
    if word == 'information':
        value = 6.4 + (0.35 if spelling[:1].isupper() else 0.0)
        if prior in PRIVACY:
            value = 4.6
        elif prior in MORE:
            value = 5.6 if prior == 'additional' else 5.0
            if previous.strip() == 'More':
                value = 3.5
        elif prior == 'contact':
            value = 5.0
        elif prior == 'the':
            value += 0.4
    elif word == 'info':
        value = 5.3
        if spelling.startswith(('_', '.')):
            value = 3.9
        elif spelling.startswith(('-', '/')):
            value = 5.9
        elif raw[:1].isspace():
            value = 4.1 if spelling == 'INFO' else 4.9
    elif word in MEDIUM_INFORMATION:
        value = 4.3
    elif word in OTHER_INFORMATION:
        value = 3.7
    elif word in INFORM_COGNATES or word == 'informational':
        value = 5.1
    elif word in {'信息', '的信息'}:
        value = 5.8
    elif '信息' in word:
        value = 3.4
    elif word == '资讯':
        value = 2.0
    elif word in INFORMING:
        value = 2.5
    elif word in {'informed', 'inf'}:
        value = 1.0
    elif word in KNOWLEDGE:
        value = 0.65
    elif word in NEWS_EDUCATION:
        value = 0.8
    elif word in {'suddenly', 'sudden', '突然'}:
        value = -2.2 if word == '突然' else (-1.75 if word == 'suddenly' else -1.3)

    joined = prior.lstrip('_.-/(') + word
    if prior and word.isalpha() and not raw[:1].isspace():
        if joined.startswith('inform') and (joined == 'information'
                or joined in MEDIUM_INFORMATION or joined in INFORM_COGNATES):
            value = 5.3
        elif joined.startswith('информац'):
            value = 3.3
    if prior in {'information', 'info'}:
        value += {'about': 0.85, 'on': 0.4, 'of': 2.1,
                  'for': 0.35, 'regarding': 0.3, 'in': 0.1}.get(word, 0.0)
    return (doc, raw), float(value)

programs.haiku:
"""Fires on the word "information" and its relatives.

The component's output is large and positive on the token "information" (with or
without a leading space or capital: " information", "Information") and on the
abbreviation "info" ("Info", "INFO", "_info", " info"). Weaker, but still clearly
positive, on "inform", "informed", "informative", and the same idea in other
languages (información, информация, 情報, 信息). A handful of ordinary words
(news, details, education, knowledge, notice, learn) give a small positive value.
Everything else is predicted as 0.

The program is a lookup on the current token only: it ignores context and earlier
tokens. Values are roughly the mean activation for each word family.
"""

READS = ()

# Words, lowercased, with leading spaces, underscores and dashes removed.
INFORMATION = {"information", "informations", "informational"}
INFO = {"info", "infos"}
INFORM_OTHER = {
    "información", "informações", "informação", "информация", "информации",
    "информацию", "информ", "情報", "信息", "资讯", "資訊",
}
SOFT = {"news", "details", "education", "educated", "educational", "knowledge",
        "notice", "learn", "formation"}


def _word(text):
    return text.lstrip(" _-").lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    if word in INFORMATION:
        value = 6.0
    elif word in INFO:
        value = 5.0
    elif word.startswith("inform") or word in INFORM_OTHER:
        value = 2.5
    elif word in SOFT:
        value = 0.8
    else:
        value = 0.0
    return carry, value

programs.sol:
"""A negative detector for short pieces ending in the written vowel u.

Standalone u/U and short u-final syllables dominate. Word boundaries weaken
these responses; uppercase acronym continuations strengthen them. Qu and
vowel blends are weaker. Longer pieces fade out. Accented-word continuations
and LaTeX Greek-letter names also have weaker responses. Smaller rules
cover Cyrillic у, umlaut ü, and the Devanagari short-u sign.
"""
import re

READS = ()
LETTERS_AT_END = re.compile(r'[^\W\d_]+$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, fragment = ('', '') if carry is None or carry[0] != doc else carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().lstrip('.,_-([<*/=')
    text = word.lower()
    boundary = raw != word
    size = len(text)
    value = 0.0
    if text.endswith('u') and text.isascii() and text.isalpha():
        if size == 1:
            if boundary:
                value = -2.0
            elif not fragment:
                value = -2.25
            elif word == 'U':
                value = -4.1 if fragment.isupper() else -2.9
            else:
                value = -2.7
        elif text.endswith('ou'):
            value = 0.0 if boundary else -0.1
        elif text.endswith('qu'):
            value = -0.35 if boundary else -0.55
        elif text.endswith('au'):
            value = -0.85 if boundary else -1.1
            if word[0].isupper():
                value -= 0.7
        elif text.endswith('eu'):
            value = -1.7 if size == 2 else -0.8
        elif size <= 3:
            value = -2.1 if boundary else -2.75
            if size == 3:
                value -= 0.25
            if word[0].isupper():
                value -= 0.6
            if word.isupper() and not boundary:
                value -= 0.8
        else:
            value = -1.3 * (0.75 ** (size - 4))
        if not boundary and fragment and not fragment.isascii():
            value *= 0.6
        if previous.endswith('\\') and text in ('mu', 'nu'):
            value = -1.5 if text == 'mu' else -1.7
    elif size <= 3 and text.endswith('у'):
        value = -0.2 if boundary else -0.5
    elif size <= 3 and text.endswith('ü'):
        value = -0.55
    elif text == 'ु':
        value = -1.0
    suffix = LETTERS_AT_END.search(raw)
    fragment = (fragment + raw if raw.isalpha() else
                suffix.group() if suffix else '')[-16:]
    return (doc, raw, fragment), float(value)

programs.luna:
"""Estimate a sparse response to u-like token endings. Bare u is strongest;
short word pieces differ depending on case, word boundary, and vowel spelling.
The values are small class averages, with a slight negative background."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.casefold()
    value = 0.0

    if lower == "u":
        if word == "U":
            value = -3.23 if token == word else -1.97
        else:
            value = -2.67 if token == word else -2.22
    elif lower.endswith("qu"):
        value = -0.45
    elif lower.endswith("au"):
        value = -0.95
    elif lower.endswith("u"):
        n = len(word)
        first = word[0]
        vowel = lower[0] in "aeiou"
        upper = first.isupper()
        if token[:1].isspace():
            if n == 2:
                if vowel:
                    value = -1.7 if upper else -0.5
                else:
                    value = -2.75 if upper else -1.98
            elif n == 3:
                value = -0.34 if upper else 0.0
            else:
                value = -0.74
        elif n == 2:
            if not first.isalpha():
                value = -2.28
            elif vowel:
                value = -0.58
            elif upper:
                value = -3.59
            else:
                value = -2.44
        elif n == 3:
            if not first.isalpha():
                value = -2.55
            elif upper:
                value = 0.04
            elif vowel:
                value = -2.53
            else:
                value = -0.48
        elif vowel:
            value = -2.0
        else:
            value = -1.0
    elif lower.endswith("у"):
        value = -0.35
    elif token.endswith("ु"):
        value = -0.9
    elif token.endswith("ゅ"):
        value = -0.7
    elif lower.endswith(("ü", "ú")):
        value = -0.45

    return carry, float(-0.0015 + value)

programs.sol:
"""Spelling-family detector for divide, multiply and split, not an arithmetic solver.

It emits negative pulses for these words, including departments ('Division'),
HTML 'div', and code 'split'. Related separation/distribution words are weaker.
Letters are joined across token boundaries; 'division of' retains a pulse on
'of'. The division sign (including a sign completed from byte fragments) and
selected non-English operation words also respond negatively. Arabic doubling
and vowel marks are a separate positive response. Other tokens receive zero.
Document changes reset the carried word.
"""
import re
READS = ()

OPERATIONS = {
    'divide': -4.7, 'divides': -4.2, 'divided': -3.8, 'dividing': -4.85,
    'division': -3.65, 'divisions': -3.1, 'divisible': -2.1,
    'divisibility': -1.6, 'divider': -2.0, 'dividers': -1.7,
    'dividend': -1.6, 'dividends': -1.7, 'divisor': -0.85, 'divisors': -0.5,
    'multiply': -3.25, 'multiplying': -3.05, 'multiplies': -2.6,
    'multiplied': -2.3, 'multiplication': -2.3, 'multiplier': -0.65,
    'split': -3.3, 'splits': -3.2, 'splitting': -2.95,
    'div': -2.0, 'divid': -3.5, 'divis': -2.15, 'multip': -1.8,
}
CHINESE_OPERATIONS = {
    '分裂': -3.6, '分割': -2.8, '分工': -2.5, '分布式': -2.1,
    '分散': -2.0, '分红': -1.8, '分解': -1.5, '分歧': -1.25,
    '分布': -1.2, '乘': -1.4, '除': -1.25, '拆': -0.9, '裂': -1.55,
}
ARABIC_MARKS = {'ّ': 3.15, 'َ': 1.25, 'ً': 0.5}


def strength(word):
    w = word.lower()
    if w in OPERATIONS:
        extra = 0.0
        if w in ('divide', 'divides', 'divided', 'dividing'):
            extra = 0.8
        if w in ('division', 'divisions'):
            extra = 0.7
        if w == 'div':
            extra = 1.0
        if w == 'multip':
            extra = 0.6
        return OPERATIONS[w] - (extra if word[0].isupper() else 0.0)
    if w.startswith('subdiv'):
        return -2.6
    if w.startswith('divers'):
        return -1.3
    if w.startswith(('diverg', 'divin', 'divor', 'separ')):
        return -0.8
    if w.startswith('multiplic'):
        return -1.7
    if w.startswith('mult') and w not in ('multiple', 'multiples', 'multitude'):
        return -1.0
    if w == 'mul':
        return -1.0
    if w.startswith('distrib'):
        return -0.6 if w.startswith('distribution') else -1.4
    if w.startswith(('spread', 'prolifer', 'partition', 'diffus', 'subtract')):
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    same_doc = carry is not None and carry[0] == doc
    previous = carry[1] if same_doc else ''
    word, value = '', 0.0
    tail = re.search(r'[^\W\d_]+$', token)
    if tail:
        part = tail.group()
        word = previous + part if tail.start() == 0 else part
        value = strength(part) or strength(word)
        if token.strip() == 'of' and previous.lower().endswith('division'):
            value = -3.2
    if token in CHINESE_OPERATIONS:
        value = CHINESE_OPERATIONS[token]
    if token.strip().startswith('раздел'):
        value = -3.15
    if token.strip().startswith('böl'):
        value = -1.8
    if '÷' in token or ('�' in token and same_doc
                        and prefix.text_prefixes[-1].endswith('÷')):
        value = -3.15
    if token in ARABIC_MARKS:
        value = ARABIC_MARKS[token]
    return (doc, word[-40:]), float(value)

programs.haiku:
"""Division, splitting and multiplying words in the text, as a negative response; Arabic shadda positive.

The component writes a strongly negative value on the token of a word about dividing or splitting
(divide, divided, division, split), a somewhat weaker one on multiplying words and on the short
piece "div", and a weak one on words about distributing, separating, spreading or diversity.
It also reads the division sign ÷ and the Chinese and Russian words for divide, split and multiply.
It is near zero everywhere else, except the Arabic shadda mark (ّ), which is positive.
"""
READS = ()
TIERS = [
    (-4.0, ("divid", "division", "split")),
    (-3.0, ("multiply", "multiplying", "multiplied", "multiplication", "multiplic")),
    (-2.0, ("div", "divisible", "divis", "dividend")),
    (-1.0, ("distribut", "separat", "spread", "subtract", "partition", "multi", "mult", "mul",
            "diverse", "diversity", "divine", "divorce", "divisor")),
]
SHADDA = "ّ"  # Arabic gemination mark
SPECIAL = {"÷": -3.0, "分裂": -3.5, "分割": -2.8, "раздел": -3.2, "除": -1.2, "乘": -1.4, "分布": -1.2}

def token_value(s):
    if s.strip() == SHADDA:
        return 3.0
    if s.strip() in SPECIAL:
        return SPECIAL[s.strip()]
    w = s.strip().lower()
    if w.startswith("multiple") or "indiv" in w:
        return 0.0
    for value, stems in TIERS:
        if w.startswith(stems):
            return value
    return 0.0

def step(carry, prefix, upstream):
    return carry, token_value(prefix.token_strings[-1])

programs.luna:
"""Recognize word beginnings about division, multiplication, or spreading.

The remembered fragment joins byte-pair pieces into the current word; it resets
when a token begins with whitespace. These lexical cues produce negative pulses.
"""

READS = ()

STRONG = ("divid", "divide", "division", "multiply", "multipli")
DIVISION = ("div", "分裂")
MULTIPLE = ("mult",)
RELATED = (
    "separ", "split", "distribut", "proliferat", "diverg", "breakdown",
    "diff", "combin", "dispers", "dağı",
)


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1].casefold()
    old_fragment = ""
    old_doc = None
    if carry is not None:
        old_fragment, old_doc = carry
    doc = prefix.document_ids[-1]
    if old_doc != doc:
        old_fragment = ""

    piece = raw.strip()
    if raw[:1].isspace() or not piece:
        word = piece
    elif piece[0].isalnum():
        word = old_fragment + piece
    else:
        word = piece

    # A word may start after punctuation inside a token (for example, `_mult`).
    word = word.lstrip("_<>/\\'\"([{")
    if any(word.startswith(root) for root in STRONG):
        value = -3.0
    elif any(word.startswith(root) for root in DIVISION):
        value = -1.5
    elif any(word.startswith(root) for root in MULTIPLE):
        value = -1.5
    elif any(word.startswith(root) for root in RELATED):
        value = -0.65
    else:
        value = 0.0

    fragment = ""
    for char in reversed(piece):
        if char.isalnum():
            fragment = char + fragment
        else:
            break
    return (fragment, doc), value
